#[test]
fn instead_of_view_triggers_drive_insert_update_delete_and_returning() {
    let (mut engine, mut budget) = test_engine();
    let output = run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE view_trigger_base (id integer PRIMARY KEY, value integer); \
         INSERT INTO view_trigger_base VALUES (1, 10), (2, 20); \
         CREATE VIEW view_trigger_target AS SELECT id, value FROM view_trigger_base; \
         CREATE FUNCTION view_trigger_write() RETURNS trigger LANGUAGE plpgsql AS \
           'BEGIN \
              IF TG_OP = ''INSERT'' THEN INSERT INTO view_trigger_base VALUES (NEW.id, NEW.value); RETURN NEW; END IF; \
              IF TG_OP = ''UPDATE'' THEN UPDATE view_trigger_base SET value = NEW.value WHERE id = OLD.id; RETURN NEW; END IF; \
              DELETE FROM view_trigger_base WHERE id = OLD.id; RETURN OLD; \
            END'; \
         CREATE TRIGGER view_trigger_write INSTEAD OF INSERT OR UPDATE OR DELETE ON view_trigger_target \
           FOR EACH ROW EXECUTE FUNCTION view_trigger_write(); \
         INSERT INTO view_trigger_target VALUES (3, 30) RETURNING id, value; \
         UPDATE view_trigger_target SET value = value + 1 WHERE id = 2 RETURNING id, value; \
         DELETE FROM view_trigger_target WHERE id = 1 RETURNING id;",
    );
    assert_eq!(
        data_rows(&output),
        ["3|30", "2|21", "1"],
        "{}",
        String::from_utf8_lossy(&output)
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT pg_get_function_arguments(p.oid), pg_get_function_identity_arguments(p.oid), \
                    pg_get_function_result(p.oid), p.probin, language.lanname \
               FROM pg_proc p JOIN pg_language language ON language.oid = p.prolang \
              WHERE p.proname = 'view_trigger_write'"
        )),
        ["||trigger||plpgsql"]
    );
    let insert_select = run_with(
        &mut engine,
        &mut budget,
        "INSERT INTO view_trigger_target (value, id) SELECT value, id FROM (VALUES (40, 4)) source(value, id) RETURNING id, value",
    );
    assert_eq!(
        data_rows(&insert_select),
        ["4|40"],
        "{}",
        String::from_utf8_lossy(&insert_select)
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT id, value FROM view_trigger_base ORDER BY id"
        )),
        ["2|21", "3|30", "4|40"]
    );
    let joined_dml = run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE view_trigger_source (id integer PRIMARY KEY, value integer); \
         INSERT INTO view_trigger_source VALUES (2, 200), (4, 400); \
         UPDATE view_trigger_target AS target SET value = source.value \
           FROM view_trigger_source AS source WHERE target.id = source.id \
           RETURNING target.id, target.value; \
         DELETE FROM view_trigger_target AS target USING view_trigger_source AS source \
           WHERE target.id = source.id AND source.id = 2 RETURNING target.id",
    );
    assert_eq!(data_rows(&joined_dml), ["2|200", "4|400", "2"]);
    run_with(
        &mut engine,
        &mut budget,
        "BEGIN; \
         UPDATE view_trigger_source SET value = 444 WHERE id = 4; \
         UPDATE view_trigger_target AS target SET value = source.value \
           FROM view_trigger_source AS source WHERE target.id = source.id; \
         ROLLBACK",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT id, value FROM view_trigger_base ORDER BY id"
        )),
        ["3|30", "4|400"]
    );
    run_with(
        &mut engine,
        &mut budget,
        "BEGIN; INSERT INTO view_trigger_target VALUES (5, 50); ROLLBACK",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT count(*) FROM view_trigger_base WHERE id = 5"
        )),
        ["0"]
    );
}

#[test]
fn instead_of_view_trigger_survives_checkpoint_recovery() {
    let mut config = test_config("instead-of-view-recovery");
    config.object_store_on = true;
    config.object_store_sim = true;
    config.wal_upload = true;
    config.wal_upload_sync = true;
    config.object_store_namespace = format!("instead-of-view-recovery-{}", std::process::id());
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    let mut budget = Budget::new(1 << 29);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let created = run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE recovered_view_base (id integer PRIMARY KEY, value integer); \
         CREATE TABLE recovered_view_source (id integer PRIMARY KEY, value integer); \
         INSERT INTO recovered_view_source VALUES (7, 77); \
         CREATE VIEW recovered_view AS SELECT id, value FROM recovered_view_base; \
         CREATE FUNCTION recovered_view_trigger() RETURNS trigger LANGUAGE plpgsql AS \
           'BEGIN \
              IF TG_OP = ''INSERT'' THEN INSERT INTO recovered_view_base VALUES (NEW.id, NEW.value); RETURN NEW; END IF; \
              IF TG_OP = ''UPDATE'' THEN UPDATE recovered_view_base SET value = NEW.value WHERE id = OLD.id; RETURN NEW; END IF; \
              DELETE FROM recovered_view_base WHERE id = OLD.id; RETURN OLD; \
            END'; \
         CREATE TRIGGER recovered_view_trigger INSTEAD OF INSERT OR UPDATE OR DELETE ON recovered_view \
           FOR EACH ROW EXECUTE FUNCTION recovered_view_trigger(); \
         ALTER TABLE recovered_view DISABLE TRIGGER recovered_view_trigger;",
    );
    assert!(!String::from_utf8_lossy(&created).contains("ERROR"));
    assert!(engine.checkpoint().unwrap());
    drop(engine);

    let mut restarted_budget = Budget::new(1 << 29);
    let mut restarted = Engine::new(&config, &mut restarted_budget).unwrap();
    let disabled = run_with(
        &mut restarted,
        &mut restarted_budget,
        "INSERT INTO recovered_view VALUES (7, 70)",
    );
    assert!(String::from_utf8_lossy(&disabled).contains("55000"));
    let recovered = run_with(
        &mut restarted,
        &mut restarted_budget,
        "ALTER TABLE recovered_view ENABLE TRIGGER recovered_view_trigger; \
             INSERT INTO recovered_view VALUES (7, 70); \
             UPDATE recovered_view AS target SET value = source.value \
               FROM recovered_view_source AS source WHERE target.id = source.id \
               RETURNING target.id, target.value; \
             DELETE FROM recovered_view AS target USING recovered_view_source AS source \
               WHERE target.id = source.id RETURNING target.id; \
             SELECT count(*) FROM recovered_view_base",
    );
    assert_eq!(
        data_rows(&recovered),
        ["7|77", "7", "0"],
        "{}",
        String::from_utf8_lossy(&recovered)
    );
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    std::fs::remove_dir_all(&config.data_dir).unwrap();
}

#[test]
fn view_trigger_is_a_drop_dependency_and_cascades_transactionally() {
    let (mut engine, mut budget) = test_engine();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE drop_view_trigger_base (id integer); \
         CREATE VIEW drop_view_trigger_target AS SELECT id FROM drop_view_trigger_base; \
         CREATE FUNCTION drop_view_trigger_function() RETURNS trigger LANGUAGE plpgsql AS \
           'BEGIN RETURN NEW; END'; \
         CREATE TRIGGER drop_view_trigger INSTEAD OF INSERT ON drop_view_trigger_target \
           FOR EACH ROW EXECUTE FUNCTION drop_view_trigger_function();",
    );
    let restricted = run_with(
        &mut engine,
        &mut budget,
        "DROP VIEW drop_view_trigger_target",
    );
    assert!(String::from_utf8_lossy(&restricted).contains("2BP01"));
    let dropped = run_with(
        &mut engine,
        &mut budget,
        "DROP VIEW drop_view_trigger_target CASCADE; \
         SELECT count(*) FROM pg_trigger WHERE tgname = 'drop_view_trigger'",
    );
    assert_eq!(data_rows(&dropped), ["0"]);
}

fn test_engine() -> (Engine, Budget) {
    test_engine_with_budget(1 << 27)
}

fn test_engine_with_budget(bytes: usize) -> (Engine, Budget) {
    // Each test gets its own journal; the caller's function name is not
    // available, so a counter differentiates them.
    use core::sync::atomic::{AtomicU32, Ordering};
    static N: AtomicU32 = AtomicU32::new(0);
    let n = N.fetch_add(1, Ordering::SeqCst);
    let name = format!("t{n}");
    let config = test_config(&name);
    let mut budget = Budget::new(bytes);
    let engine = Engine::new(&config, &mut budget).unwrap();
    (engine, budget)
}

fn run_with(engine: &mut Engine, budget: &mut Budget, sql_text: &str) -> Vec<u8> {
    let mut guc = GucState::new();
    run_with_guc(engine, budget, sql_text, 1 << 18, &mut guc)
}

fn copy_line(
    engine: &mut Engine,
    budget: &mut Budget,
    setup: &crate::sql::exec::CopySetup,
    txn: &mut TxnState,
    seq_session: &crate::sql::guc::SeqSession,
    arena: &Arena,
    line: &[u8],
) -> Result<crate::sql::exec::CopyRowOutcome, SqlError> {
    let mut send = crate::mem::FixedBuf::new(budget, "copy test response", 1 << 16).unwrap();
    let mut responder = Responder::new(&mut send);
    engine.copy_row_line(setup, txn, seq_session, arena, &mut responder, line)
}

fn copy_binary_row(
    engine: &mut Engine,
    budget: &mut Budget,
    setup: &crate::sql::exec::CopySetup,
    txn: &mut TxnState,
    seq_session: &crate::sql::guc::SeqSession,
    arena: &Arena,
    row: &[u8],
) -> Result<crate::sql::exec::CopyRowOutcome, SqlError> {
    let mut send = crate::mem::FixedBuf::new(budget, "copy test response", 1 << 16).unwrap();
    let mut responder = Responder::new(&mut send);
    engine.copy_row_binary(setup, txn, seq_session, arena, &mut responder, row)
}

fn finish_copy(
    engine: &mut Engine,
    budget: &mut Budget,
    setup: &crate::sql::exec::CopySetup,
    txn: &mut TxnState,
    guc: &GucState,
) -> Result<(), SqlError> {
    let mut send = crate::mem::FixedBuf::new(budget, "copy finish response", 1 << 16).unwrap();
    engine.copy_finish(setup, txn, guc, &mut Responder::new(&mut send))
}

fn run_with_arena_bytes(
    engine: &mut Engine,
    budget: &mut Budget,
    sql_text: &str,
    arena_bytes: usize,
) -> Vec<u8> {
    let mut guc = GucState::new();
    run_with_guc(engine, budget, sql_text, arena_bytes, &mut guc)
}

fn assert_cold_pax_query(
    config: &Config,
    sql_text: &str,
    expected: &[&str],
    max_object_read_bytes: Option<u64>,
) {
    let mut budget = Budget::new(1 << 30);
    let mut engine = Engine::new(config, &mut budget).unwrap();
    let before = engine.storage.block_io_stats();
    let result = run_with_arena_bytes(&mut engine, &mut budget, sql_text, 1 << 20);
    assert_eq!(
        data_rows(&result),
        expected,
        "cold PAX query failed: {sql_text}\n{}",
        String::from_utf8_lossy(&result),
    );
    if let Some(max_object_read_bytes) = max_object_read_bytes {
        let reads = engine.storage.block_io_stats().saturating_sub(before);
        assert!(
            reads.object_read_bytes < max_object_read_bytes,
            "cold PAX query must read only its demanded extents: {sql_text}; bytes={}",
            reads.object_read_bytes
        );
    }
}

#[inline(never)]
fn prepare_cold_pax_fixture(config: &Config) {
    let mut budget = Budget::new(1 << 30);
    let mut engine = Engine::new(config, &mut budget).unwrap();
    let mut definition = String::from("CREATE TABLE wide_pax (id int PRIMARY KEY");
    let mut selected = String::from("i");
    for column in 0..20 {
        definition.push_str(&format!(", payload_{column} text"));
        selected.push_str(", repeat('x', 2048)");
    }
    definition.push(')');
    assert!(
        !String::from_utf8_lossy(&run_with_arena_bytes(
            &mut engine,
            &mut budget,
            &definition,
            1 << 16,
        ))
        .contains("ERROR")
    );
    for start in (1..=300).step_by(5) {
        let inserted = run_with_arena_bytes(
            &mut engine,
            &mut budget,
            &format!(
                "INSERT INTO wide_pax SELECT {selected} FROM generate_series({start}, {}) AS g(i)",
                start + 4
            ),
            2 << 20,
        );
        assert!(
            !String::from_utf8_lossy(&inserted).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&inserted)
        );
    }
    let right_definition = definition.replacen("wide_pax", "wide_pax_right", 1);
    assert!(
        !String::from_utf8_lossy(&run_with_arena_bytes(
            &mut engine,
            &mut budget,
            &right_definition,
            1 << 16,
        ))
        .contains("ERROR")
    );
    for start in (1..=300).step_by(5) {
        let inserted = run_with_arena_bytes(
            &mut engine,
            &mut budget,
            &format!(
                "INSERT INTO wide_pax_right SELECT {selected} FROM generate_series({start}, {}) AS g(i)",
                start + 4
            ),
            2 << 20,
        );
        assert!(
            !String::from_utf8_lossy(&inserted).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&inserted)
        );
    }
    let third_definition = definition.replacen("wide_pax", "wide_pax_third", 1);
    assert!(
        !String::from_utf8_lossy(&run_with_arena_bytes(
            &mut engine,
            &mut budget,
            &third_definition,
            1 << 16,
        ))
        .contains("ERROR")
    );
    let inserted = run_with_arena_bytes(
        &mut engine,
        &mut budget,
        &format!(
            "INSERT INTO wide_pax_third SELECT {selected} FROM generate_series(287, 287) AS g(i)"
        ),
        1 << 16,
    );
    assert!(
        !String::from_utf8_lossy(&inserted).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&inserted)
    );
    let target = run_with_arena_bytes(
        &mut engine,
        &mut budget,
        "CREATE TABLE wide_pax_target (id int PRIMARY KEY, payload text); \
         INSERT INTO wide_pax_target VALUES (287, 'before')",
        1 << 16,
    );
    assert!(
        !String::from_utf8_lossy(&target).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&target)
    );
    assert!(engine.checkpoint().unwrap());
}

fn run_with_guc(
    engine: &mut Engine,
    budget: &mut Budget,
    sql_text: &str,
    arena_bytes: usize,
    guc: &mut GucState,
) -> Vec<u8> {
    let mut buffer = crate::mem::FixedBuf::new(budget, "send", 1 << 18).unwrap();
    let arena = Arena::new(budget, "sql", arena_bytes).unwrap();
    let mut txn = TxnState::new(budget, 1024).unwrap();
    let mut pool = test_pool(budget);
    let mut responder = Responder::new(&mut buffer);
    engine
        .execute_simple(
            sql_text,
            &arena,
            &mut txn,
            &mut pool,
            &mut test_cursors(budget),
            guc,
            &mut responder,
            1,
        )
        .unwrap();
    buffer.readable().to_vec()
}

fn describe_with(engine: &mut Engine, budget: &mut Budget, sql_text: &str) -> Vec<u8> {
    let mut buffer = crate::mem::FixedBuf::new(budget, "describe send", 1 << 18).unwrap();
    let arena = Arena::new(budget, "describe sql", 1 << 18).unwrap();
    let transaction = TxnState::new(budget, 1024).unwrap();
    let described = {
        let mut responder =
            Responder::for_describe(&mut buffer, crate::pg::respond::ResultFmt::ALL_TEXT);
        engine
            .describe(sql_text, &arena, &transaction, None, &mut responder)
            .unwrap()
    };
    assert!(described, "{}", String::from_utf8_lossy(buffer.readable()));
    buffer.readable().to_vec()
}

/// Stages one implicit transaction through the same executor entry point as a
/// connection, deliberately leaving publication to the caller's flush
/// boundary.
fn stage_without_publication(engine: &mut Engine, budget: &mut Budget, sql_text: &str) {
    let mut buffer = crate::mem::FixedBuf::new(budget, "send", 1 << 18).unwrap();
    let arena = Arena::new(budget, "sql", 1 << 18).unwrap();
    let mut txn = TxnState::new(budget, 1024).unwrap();
    let mut pool = test_pool(budget);
    let mut cursors = test_cursors(budget);
    let mut guc = GucState::new();
    let mut responder = Responder::new(&mut buffer);
    engine
        .execute_simple_from(
            sql_text,
            0,
            &arena,
            &mut txn,
            &mut pool,
            &mut cursors,
            &mut guc,
            &mut responder,
            1,
            false,
        )
        .unwrap();
}

/// Runs one simple-query message as a specific connection id (for LISTEN /
/// NOTIFY, whose semantics are cross-connection).
fn run_as(engine: &mut Engine, budget: &mut Budget, conn_id: i32, sql_text: &str) -> Vec<u8> {
    let mut buffer = crate::mem::FixedBuf::new(budget, "send", 1 << 18).unwrap();
    let arena = Arena::new(budget, "sql", 1 << 18).unwrap();
    let mut txn = TxnState::new(budget, 1024).unwrap();
    let mut pool = test_pool(budget);
    let mut guc = GucState::new();
    let mut responder = Responder::new(&mut buffer);
    engine
        .execute_simple(
            sql_text,
            &arena,
            &mut txn,
            &mut pool,
            &mut test_cursors(budget),
            &mut guc,
            &mut responder,
            conn_id,
        )
        .unwrap();
    buffer.readable().to_vec()
}

fn test_pool(budget: &mut Budget) -> SqlPreparedPool {
    let mut c = Config::default_dev();
    c.max_prepared = 4;
    c.prepared_bytes = 1024;
    SqlPreparedPool::new(&c, budget).unwrap()
}

fn test_cursors(budget: &mut Budget) -> crate::sql::cursor::CursorPool {
    let mut c = Config::default_dev();
    c.max_cursors = 2;
    c.cursor_bytes = 16 * 1024;
    crate::sql::cursor::CursorPool::new(&c, budget).unwrap()
}

#[test]
fn role_catalog_is_transactional_and_attribute_complete() {
    let (mut engine, mut budget) = test_engine();
    let output = run_with(
        &mut engine,
        &mut budget,
        "CREATE ROLE analyst LOGIN CREATEDB NOINHERIT CONNECTION LIMIT 3 PASSWORD 'secret'
             VALID UNTIL '2030-01-02 03:04:05+00';
         SELECT rolname, rolsuper, rolinherit, rolcreatedb, rolcanlogin,
                rolconnlimit, rolvaliduntil IS NOT NULL, rolreplication, rolbypassrls
           FROM pg_roles WHERE rolname = 'analyst';
         ALTER USER analyst WITH NOLOGIN REPLICATION BYPASSRLS;
         SELECT rolcanlogin, rolreplication, rolbypassrls
           FROM pg_roles WHERE rolname = 'analyst';
         SET ROLE analyst;
         SELECT current_user, session_user, current_role;
         RESET ROLE;
         SELECT current_user, session_user, current_role;",
    );
    assert_eq!(
        data_rows(&output),
        [
            "analyst|f|f|t|t|3|t|f|f",
            "f|t|t",
            "analyst|postgres|analyst",
            "postgres|postgres|postgres",
        ],
        "{}",
        String::from_utf8_lossy(&output)
    );

    let output = run_with(
        &mut engine,
        &mut budget,
        "BEGIN;
         CREATE GROUP transient;
         SELECT count(*) FROM pg_roles WHERE rolname = 'transient';
         ROLLBACK;
         SELECT count(*) FROM pg_roles WHERE rolname = 'transient';",
    );
    assert_eq!(data_rows(&output), ["1", "0"]);

    let output = run_with(
        &mut engine,
        &mut budget,
        "DROP ROLE analyst; SELECT count(*) FROM pg_roles WHERE rolname = 'analyst'",
    );
    assert_eq!(
        data_rows(&output),
        ["0"],
        "{}",
        String::from_utf8_lossy(&output)
    );
}

#[test]
fn role_connection_limit_is_reserved_and_released_exactly() {
    let (mut engine, mut budget) = test_engine();
    let output = run_with(
        &mut engine,
        &mut budget,
        "CREATE ROLE limited_login LOGIN CONNECTION LIMIT 1",
    );
    assert!(!String::from_utf8_lossy(&output).contains("ERROR"));
    let login = engine.role_login("limited_login").unwrap();
    assert!(login.can_login && login.valid);
    assert!(engine.reserve_role_connection(login));
    assert!(!engine.reserve_role_connection(login));
    engine.release_role_connection(login.slot);
    assert!(engine.reserve_role_connection(login));
    engine.release_role_connection(login.slot);
}

