#[test]
fn derived_record_expansion_keeps_names_and_ordinal_targets() {
    let (mut engine, mut budget) = test_engine();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE record_source (priority integer, label text); \
         INSERT INTO record_source VALUES (2, 'second'), (1, 'first')",
    );
    let query = "SELECT (record_value).* \
                 FROM (SELECT record_source AS record_value FROM record_source) derived \
                 ORDER BY 1";
    let result = run_with(&mut engine, &mut budget, query);
    assert_eq!(row_description_names(&result), ["priority", "label"]);
    assert_eq!(data_rows(&result), ["1|first", "2|second"]);
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "WITH records AS (SELECT record_source AS record_value FROM record_source) \
             SELECT (record_value).* FROM records ORDER BY 1"
        )),
        ["1|first", "2|second"]
    );
    let unioned = run_with(
        &mut engine,
        &mut budget,
        "SELECT (record_value).* FROM ( \
             SELECT record_source AS record_value FROM record_source WHERE priority = 1 \
             UNION ALL \
             SELECT record_source FROM record_source WHERE priority = 2 \
         ) records ORDER BY 1",
    );
    assert_eq!(
        data_rows(&unioned),
        ["1|first", "2|second"],
        "{}",
        String::from_utf8_lossy(&unioned)
    );
    let grouped = run_with(
        &mut engine,
        &mut budget,
        "SELECT (record_value).* \
         FROM (SELECT record_source AS record_value FROM record_source) derived \
         GROUP BY 1, 2 ORDER BY 2 DESC",
    );
    assert_eq!(
        data_rows(&grouped),
        ["2|second", "1|first"],
        "{}",
        String::from_utf8_lossy(&grouped)
    );
}

#[test]
fn object_resident_set_records_keep_their_structural_fields() {
    use core::sync::atomic::{AtomicU32, Ordering};

    static NEXT_NAMESPACE: AtomicU32 = AtomicU32::new(0);
    let sequence = NEXT_NAMESPACE.fetch_add(1, Ordering::SeqCst);
    let mut config = test_config(&format!("set-record-spill-{sequence}"));
    config.object_store_on = true;
    config.object_store_sim = true;
    config.object_store_namespace =
        format!("sql-set-record-spill-{}-{sequence}", std::process::id());
    config.object_store_response_bytes = 1 << 20;
    config.block_cache_bytes = crate::store::BLOCK_SIZE;
    config.disk_cache_bytes = crate::store::BLOCK_SIZE;
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    let mut budget = Budget::new(1 << 28);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE spill_record_source (priority integer, label text); \
         INSERT INTO spill_record_source VALUES (2, 'second'), (1, 'first')",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT (record_value).* FROM ( \
                 SELECT spill_record_source AS record_value FROM spill_record_source WHERE priority = 1 \
                 UNION ALL \
                 SELECT spill_record_source FROM spill_record_source WHERE priority = 2 \
             ) records ORDER BY 1"
        )),
        ["1|first", "2|second"]
    );
}

#[test]
fn catalog_object_columns_preserve_identity_and_catalog_text() {
    let (mut engine, mut budget) = test_engine();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE ROLE catalog_object_role; \
         CREATE SCHEMA catalog_object_schema; \
         CREATE TABLE catalog_object_reference (id integer); \
         CREATE TABLE catalog_object_values ( \
             relation_value regclass DEFAULT 'catalog_object_reference'::regclass, \
             role_value regrole DEFAULT 'catalog_object_role'::regrole, \
             schema_value regnamespace DEFAULT 'catalog_object_schema'::regnamespace \
         ); \
         INSERT INTO catalog_object_values DEFAULT VALUES; \
         INSERT INTO catalog_object_values VALUES ( \
             'catalog_object_reference', 'catalog_object_role', 'catalog_object_schema' \
         )",
    );
    let output = run_with(
        &mut engine,
        &mut budget,
        "SELECT relation_value, role_value, schema_value, \
                pg_typeof(relation_value), pg_typeof(role_value), pg_typeof(schema_value) \
         FROM catalog_object_values ORDER BY relation_value",
    );
    assert_eq!(
        data_rows(&output),
        [
            "catalog_object_reference|catalog_object_role|catalog_object_schema|regclass|regrole|regnamespace",
            "catalog_object_reference|catalog_object_role|catalog_object_schema|regclass|regrole|regnamespace",
        ]
    );
    assert_eq!(
        row_description_type_oids(&run_with(
            &mut engine,
            &mut budget,
            "SELECT relation_value, role_value, schema_value FROM catalog_object_values",
        )),
        [
            crate::sql::types::oid::REGCLASS,
            crate::sql::types::oid::REGROLE,
            crate::sql::types::oid::REGNAMESPACE,
        ]
    );
    run_with(
        &mut engine,
        &mut budget,
        "ALTER TABLE catalog_object_reference RENAME TO catalog_object_renamed",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT relation_value FROM catalog_object_values ORDER BY relation_value",
        )),
        ["catalog_object_renamed", "catalog_object_renamed"]
    );
}

