#[test]
fn catalog_oid_columns_unify_with_regclass_set_operands() {
    let (mut engine, mut budget) = test_engine();
    let output = run_with(
        &mut engine,
        &mut budget,
        "SELECT classid FROM pg_depend UNION ALL SELECT 'pg_opfamily'::regclass",
    );
    assert_eq!(
        row_description_type_oids(&output),
        [crate::sql::types::oid::OID]
    );
    let output = run_with(
        &mut engine,
        &mut budget,
        "SELECT classid, objid, refclassid, refobjid, deptype FROM pg_depend \
         UNION ALL \
         SELECT 'pg_opfamily'::regclass, amopfamily, refclassid, refobjid, deptype \
         FROM pg_depend d, pg_amop o \
         WHERE classid = 'pg_amop'::regclass AND objid = o.oid",
    );
    assert!(
        !message_types(&output).contains(&b'E'),
        "{}",
        String::from_utf8_lossy(&output)
    );
    assert_eq!(
        row_description_type_oids(&output),
        [
            crate::sql::types::oid::OID,
            crate::sql::types::oid::OID,
            crate::sql::types::oid::OID,
            crate::sql::types::oid::OID,
            crate::sql::types::oid::BPCHAR,
        ]
    );
}

#[test]
fn declared_user_types_survive_protocol_description_and_parameter_inference() {
    let (mut engine, mut budget) = test_engine();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE TYPE protocol_state AS ENUM ('ready'); \
         CREATE DOMAIN protocol_count AS integer CHECK (VALUE > 0); \
         CREATE TABLE protocol_types (state protocol_state, count protocol_count)",
    );
    let enum_oid = crate::sql::types::oid::enum_oid(
        engine
            .storage
            .enum_slot("public", "protocol_state", 0)
            .unwrap() as u16,
    );
    let domain_oid = crate::sql::types::oid::domain_oid(
        engine
            .storage
            .domain_slot("public", "protocol_count", 0)
            .unwrap() as u16,
    );

    for query in [
        "SELECT state, count FROM protocol_types",
        "SELECT * FROM protocol_types",
        "SELECT (protocol_types).* FROM protocol_types",
    ] {
        assert_eq!(
            row_description_type_oids(&run_with(&mut engine, &mut budget, query)),
            [enum_oid, crate::sql::types::oid::INT4],
            "{query}"
        );
    }
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT atttypid FROM pg_attribute \
             WHERE attrelid = 'protocol_types'::regclass AND attnum > 0 ORDER BY attnum",
        )),
        [enum_oid.to_string(), domain_oid.to_string()]
    );

    let arena = Arena::new(&mut budget, "parameter inference", 1 << 18).unwrap();
    let transaction = TxnState::new(&mut budget, 64).unwrap();
    let inferred = engine.infer_param_types(
        "INSERT INTO protocol_types (state, count) VALUES ($1, $2)",
        &arena,
        &transaction,
        &[0; MAX_BIND_PARAMS],
    );
    assert_eq!(inferred[..2], [enum_oid, domain_oid]);
    let inferred = engine.infer_param_types(
        "UPDATE protocol_types SET count = $1 WHERE state = $2",
        &arena,
        &transaction,
        &[0; MAX_BIND_PARAMS],
    );
    assert_eq!(inferred[..2], [domain_oid, enum_oid]);
    let inferred = engine.infer_param_types(
        "SELECT p.state, count(*) FROM protocol_types p \
         JOIN protocol_types q ON p.count = q.count \
         WHERE p.state = $2 GROUP BY p.state HAVING count(*) >= $1",
        &arena,
        &transaction,
        &[0; MAX_BIND_PARAMS],
    );
    assert_eq!(inferred[..2], [crate::sql::types::oid::INT8, enum_oid]);
}

#[test]
fn range_and_multirange_arrays_keep_catalog_and_durable_identity() {
    let (mut engine, mut budget) = test_engine();
    let output = run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE range_array_values (\
           int4_ranges int4range[], int8_ranges int8range[], numeric_ranges numrange[],\
           date_ranges daterange[], timestamp_ranges tsrange[], timestamptz_ranges tstzrange[],\
           int4_multiranges int4multirange[], int8_multiranges int8multirange[],\
           numeric_multiranges nummultirange[], date_multiranges datemultirange[],\
           timestamp_multiranges tsmultirange[], timestamptz_multiranges tstzmultirange[]\
         ); \
         INSERT INTO range_array_values VALUES (\
           ARRAY['[1,3)'::int4range], ARRAY['[1,3)'::int8range], ARRAY['[1.5,3.5)'::numrange],\
           ARRAY['[2020-01-01,2020-01-03)'::daterange],\
           ARRAY['[2020-01-01 00:00:00,2020-01-02 00:00:00)'::tsrange],\
           ARRAY['[2020-01-01 00:00:00+00,2020-01-02 00:00:00+00)'::tstzrange],\
           ARRAY['{[1,3)}'::int4multirange], ARRAY['{[1,3)}'::int8multirange],\
           ARRAY['{[1.5,3.5)}'::nummultirange], ARRAY['{[2020-01-01,2020-01-03)}'::datemultirange],\
           ARRAY['{[2020-01-01 00:00:00,2020-01-02 00:00:00)}'::tsmultirange],\
           ARRAY['{[2020-01-01 00:00:00+00,2020-01-02 00:00:00+00)}'::tstzmultirange]\
         ); \
         SELECT pg_typeof(int4_ranges), pg_typeof(int8_ranges), pg_typeof(numeric_ranges),\
                pg_typeof(date_ranges), pg_typeof(timestamp_ranges), pg_typeof(timestamptz_ranges),\
                pg_typeof(int4_multiranges), pg_typeof(int8_multiranges), pg_typeof(numeric_multiranges),\
                pg_typeof(date_multiranges), pg_typeof(timestamp_multiranges), pg_typeof(timestamptz_multiranges)\
           FROM range_array_values",
    );
    assert_eq!(
        data_rows(&output),
        [
            "int4range[]|int8range[]|numrange[]|daterange[]|tsrange[]|tstzrange[]|int4multirange[]|int8multirange[]|nummultirange[]|datemultirange[]|tsmultirange[]|tstzmultirange[]"
        ],
        "{}",
        String::from_utf8_lossy(&output)
    );
    let oids = row_description_type_oids(&run_with(
        &mut engine,
        &mut budget,
        "SELECT int4_ranges, int8_ranges, numeric_ranges, date_ranges, timestamp_ranges, timestamptz_ranges, \
                int4_multiranges, int8_multiranges, numeric_multiranges, date_multiranges, timestamp_multiranges, timestamptz_multiranges \
           FROM range_array_values",
    ));
    assert_eq!(
        oids,
        [
            3905, 3927, 3907, 3913, 3909, 3911, 6150, 6157, 6151, 6155, 6152, 6153
        ]
    );
}

#[test]
fn range_and_multirange_arrays_survive_wal_and_checkpoint_recovery() {
    let config = test_config("range-array-restart");
    {
        let mut budget = Budget::new(1 << 26);
        let mut engine = Engine::new(&config, &mut budget).unwrap();
        run_with(
            &mut engine,
            &mut budget,
            "CREATE TABLE durable_range_arrays (\
               int4_values int4range[], int8_values int8range[], numeric_values numrange[],\
               date_values daterange[], timestamp_values tsrange[], timestamptz_values tstzrange[],\
               int4_multi int4multirange[], int8_multi int8multirange[], numeric_multi nummultirange[],\
               date_multi datemultirange[], timestamp_multi tsmultirange[], timestamptz_multi tstzmultirange[]\
             ); \
             INSERT INTO durable_range_arrays VALUES (\
               ARRAY['[1,3)'::int4range], ARRAY['[1,3)'::int8range], ARRAY['[1.5,3.5)'::numrange],\
               ARRAY['[2020-01-01,2020-01-03)'::daterange],\
               ARRAY['[2020-01-01 00:00:00,2020-01-02 00:00:00)'::tsrange],\
               ARRAY['[2020-01-01 00:00:00+00,2020-01-02 00:00:00+00)'::tstzrange],\
               ARRAY['{[1,3)}'::int4multirange], ARRAY['{[1,3)}'::int8multirange],\
               ARRAY['{[1.5,3.5)}'::nummultirange], ARRAY['{[2020-01-01,2020-01-03)}'::datemultirange],\
               ARRAY['{[2020-01-01 00:00:00,2020-01-02 00:00:00)}'::tsmultirange],\
               ARRAY['{[2020-01-01 00:00:00+00,2020-01-02 00:00:00+00)}'::tstzmultirange]\
             )",
        );
        run_with(&mut engine, &mut budget, "CHECKPOINT");
        engine.commit_wal().unwrap();
    }
    let mut budget = Budget::new(1 << 26);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let output = run_with(
        &mut engine,
        &mut budget,
        "SELECT * FROM durable_range_arrays",
    );
    assert_eq!(
        data_rows(&output),
        [
            "{\"[1,3)\"}|{\"[1,3)\"}|{\"[1.5,3.5)\"}|{\"[2020-01-01,2020-01-03)\"}|{\"[\\\"2020-01-01 00:00:00\\\",\\\"2020-01-02 00:00:00\\\")\"}|{\"[\\\"2020-01-01 00:00:00+00\\\",\\\"2020-01-02 00:00:00+00\\\")\"}|{\"{[1,3)}\"}|{\"{[1,3)}\"}|{\"{[1.5,3.5)}\"}|{\"{[2020-01-01,2020-01-03)}\"}|{\"{[\\\"2020-01-01 00:00:00\\\",\\\"2020-01-02 00:00:00\\\")}\"}|{\"{[\\\"2020-01-01 00:00:00+00\\\",\\\"2020-01-02 00:00:00+00\\\")}\"}"
        ],
        "{}",
        String::from_utf8_lossy(&output)
    );
}

#[test]
fn oid_arrays_keep_catalog_identity_and_survive_recovery() {
    let config = test_config("oid-array-restart");
    {
        let mut budget = Budget::new(1 << 26);
        let mut engine = Engine::new(&config, &mut budget).unwrap();
        let created = run_with(
            &mut engine,
            &mut budget,
            "CREATE TABLE durable_oid_arrays (values oid[])",
        );
        assert!(
            !String::from_utf8_lossy(&created).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&created)
        );
        run_with(
            &mut engine,
            &mut budget,
            "CREATE TABLE durable_oid_defaults (value oid DEFAULT 4294967295::oid); \
             INSERT INTO durable_oid_defaults DEFAULT VALUES",
        );
        let inserted = run_with(
            &mut engine,
            &mut budget,
            "INSERT INTO durable_oid_arrays VALUES (ARRAY[1::oid, NULL, 4294967295::oid])",
        );
        assert!(
            !String::from_utf8_lossy(&inserted).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&inserted)
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT 4294967295::oid, (4294967295::oid)::text, 4294967295::oid = 4294967295::oid",
            )),
            ["4294967295|4294967295|t"],
        );
        run_with(
            &mut engine,
            &mut budget,
            "CREATE VIEW durable_oid_view AS SELECT values FROM durable_oid_arrays",
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT pg_get_viewdef(oid) IS NOT NULL FROM pg_class WHERE relname = 'durable_oid_view'",
            )),
            ["t"],
        );
        run_with(&mut engine, &mut budget, "CHECKPOINT");
        let described = row_description_type_oids(&run_with(
            &mut engine,
            &mut budget,
            "SELECT values FROM durable_oid_arrays",
        ));
        assert_eq!(described, [crate::sql::types::oid::OID_ARRAY]);
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT pg_typeof(values), values::text FROM durable_oid_arrays",
            )),
            ["oid[]|{1,NULL,4294967295}"],
        );
        engine.commit_wal().unwrap();
    }
    let mut budget = Budget::new(1 << 26);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT pg_typeof(values), values::text FROM durable_oid_arrays",
        )),
        ["oid[]|{1,NULL,4294967295}"],
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT value::text FROM durable_oid_defaults",
        )),
        ["4294967295"],
    );
}

#[test]
fn binary_parameters_resolve_catalog_types_before_decoding() {
    let (mut engine, mut budget) = test_engine();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE TYPE binary_state AS ENUM ('ready', 'blocked'); \
         CREATE DOMAIN binary_positive AS integer CHECK (VALUE > 0); \
         CREATE DOMAIN binary_required AS integer NOT NULL; \
         CREATE TYPE binary_coordinate AS (x integer, y integer); \
         CREATE DOMAIN binary_coordinate_domain AS binary_coordinate",
    );
    let enum_oid = crate::sql::types::oid::enum_oid(
        engine
            .storage
            .enum_slot("public", "binary_state", 0)
            .unwrap() as u16,
    );
    let domain_oid = crate::sql::types::oid::domain_oid(
        engine
            .storage
            .domain_slot("public", "binary_positive", 0)
            .unwrap() as u16,
    );
    let composite_oid = crate::sql::types::oid::composite_oid(
        engine
            .storage
            .composite_slot("public", "binary_coordinate", 0)
            .unwrap() as u16,
    );
    let composite_domain_oid = crate::sql::types::oid::domain_oid(
        engine
            .storage
            .domain_slot("public", "binary_coordinate_domain", 0)
            .unwrap() as u16,
    );
    let mut transaction = TxnState::new(&mut budget, 64).unwrap();
    let arena = Arena::new(&mut budget, "binary parameter", 1 << 18).unwrap();

    let inferred = engine.infer_param_types(
        "SELECT $1::record",
        &arena,
        &transaction,
        &[0; MAX_BIND_PARAMS],
    );
    assert_eq!(inferred[0], crate::sql::types::oid::RECORD);

    assert_eq!(
        engine
            .decode_binary_parameter(enum_oid, b"ready", &arena, 0)
            .unwrap()
            .to_string(),
        "ready"
    );
    assert_eq!(
        engine
            .decode_binary_parameter(domain_oid, &7_i32.to_be_bytes(), &arena, 0)
            .unwrap()
            .to_string(),
        "7"
    );
    let composite_binary = [
        0, 0, 0, 2, // field count
        0, 0, 0, 23, 0, 0, 0, 4, 0, 0, 0, 4, // x int4
        0, 0, 0, 23, 0, 0, 0, 4, 0, 0, 0, 8, // y int4
    ];
    assert_eq!(
        engine
            .decode_binary_parameter(composite_oid, &composite_binary, &arena, 0)
            .unwrap()
            .to_string(),
        "(4,8)"
    );
    assert_eq!(
        engine
            .decode_binary_parameter(composite_domain_oid, &composite_binary, &arena, 0)
            .unwrap()
            .to_string(),
        "(4,8)"
    );
    let composite_array_oid = crate::sql::types::oid::composite_array_oid(
        engine
            .storage
            .composite_slot("public", "binary_coordinate", 0)
            .unwrap() as u16,
    );
    let mut composite_array_binary = Vec::new();
    composite_array_binary.extend_from_slice(&1_i32.to_be_bytes());
    composite_array_binary.extend_from_slice(&0_i32.to_be_bytes());
    composite_array_binary.extend_from_slice(&composite_oid.to_be_bytes());
    composite_array_binary.extend_from_slice(&1_i32.to_be_bytes());
    composite_array_binary.extend_from_slice(&1_i32.to_be_bytes());
    composite_array_binary.extend_from_slice(&(composite_binary.len() as i32).to_be_bytes());
    composite_array_binary.extend_from_slice(&composite_binary);
    let composite_array = engine
        .decode_binary_parameter(composite_array_oid, &composite_array_binary, &arena, 0)
        .unwrap();
    assert_eq!(composite_array.to_string(), "{\"(4,8)\"}");
    let Datum::Array { element, raw } = composite_array else {
        panic!("named-composite array decoded as a non-array")
    };
    let Some(Datum::CompositeText {
        physical_fields, ..
    }) = crate::sql::array::get(raw, element, 0)
    else {
        panic!("named-composite array element lost its stored layout")
    };
    assert_eq!(
        physical_fields, 2,
        "binary input retains the composite layout"
    );
    run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE binary_coordinate_arrays (values binary_coordinate[])",
    );
    let mut send =
        crate::mem::FixedBuf::new(&mut budget, "binary parameter send", 1 << 16).unwrap();
    let mut pool = test_pool(&mut budget);
    let mut cursors = test_cursors(&mut budget);
    let mut guc = GucState::new();
    {
        let mut responder =
            Responder::for_execute(&mut send, crate::pg::respond::ResultFmt::ALL_TEXT);
        assert!(matches!(
            engine
                .execute_extended(
                    "INSERT INTO binary_coordinate_arrays VALUES ($1)",
                    &arena,
                    &[composite_array],
                    &[composite_array.type_oid()],
                    &mut transaction,
                    &mut pool,
                    &mut cursors,
                    &mut guc,
                    &mut responder,
                    1,
                    false,
                )
                .unwrap(),
            ExtendedExecutionStatus::Complete(true)
        ));
    }
    engine.commit_txn(&mut transaction, &guc).unwrap();
    let mut composite_domain_array_binary = composite_array_binary.clone();
    composite_domain_array_binary[8..12].copy_from_slice(&composite_domain_oid.to_be_bytes());
    let composite_domain_array_oid = crate::sql::types::oid::domain_array_oid(
        engine
            .storage
            .domain_slot("public", "binary_coordinate_domain", 0)
            .unwrap() as u16,
    );
    assert_eq!(
        engine
            .decode_binary_parameter(
                composite_domain_array_oid,
                &composite_domain_array_binary,
                &arena,
                0,
            )
            .unwrap()
            .to_string(),
        "{\"(4,8)\"}"
    );
    run_with(
        &mut engine,
        &mut budget,
        "ALTER TYPE binary_coordinate ADD ATTRIBUTE z integer",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT (values[1]).x, (values[1]).z FROM binary_coordinate_arrays",
        )),
        ["4|NULL"],
        "binary Bound composite arrays preserve their pre-evolution layout"
    );
    let evolved_composite_binary = [
        0, 0, 0, 3, // field count
        0, 0, 0, 23, 0, 0, 0, 4, 0, 0, 0, 4, // x int4
        0, 0, 0, 23, 0, 0, 0, 4, 0, 0, 0, 8, // y int4
        0, 0, 0, 23, 0, 0, 0, 4, 0, 0, 0, 12, // z int4
    ];
    assert_eq!(
        engine
            .decode_binary_parameter(composite_oid, &evolved_composite_binary, &arena, 0)
            .unwrap()
            .to_string(),
        "(4,8,12)"
    );
    assert_eq!(
        engine
            .decode_binary_parameter(crate::sql::types::oid::UNKNOWN, b"wire text", &arena, 0)
            .unwrap()
            .to_string(),
        "wire text"
    );
    // Text Bind uses the same catalog resolver as binary Bind.  In particular,
    // the format bit cannot decide whether a domain, enum, or array constraint
    // is observed by the executor.
    assert_eq!(
        engine
            .decode_text_parameter(crate::sql::types::oid::INT4, b"7", &arena, 0)
            .unwrap()
            .to_string(),
        "7"
    );
    assert_eq!(
        engine
            .decode_text_parameter(enum_oid, b"ready", &arena, 0)
            .unwrap()
            .to_string(),
        "ready"
    );
    assert_eq!(
        engine
            .decode_text_parameter(domain_oid, b"7", &arena, 0)
            .unwrap()
            .to_string(),
        "7"
    );
    assert_eq!(
        engine
            .decode_text_parameter(crate::sql::types::oid::UNKNOWN, b"wire text", &arena, 0)
            .unwrap()
            .to_string(),
        "wire text"
    );
    let invalid_text = engine
        .decode_text_parameter(crate::sql::types::oid::TEXT, b"\xff", &arena, 0)
        .unwrap_err();
    assert_eq!(invalid_text.sqlstate, sqlstate::CHARACTER_NOT_IN_REPERTOIRE);
    let invalid_text_enum = engine
        .decode_text_parameter(enum_oid, b"missing", &arena, 0)
        .unwrap_err();
    assert_eq!(
        invalid_text_enum.sqlstate,
        sqlstate::INVALID_TEXT_REPRESENTATION
    );
    let invalid_text_domain = engine
        .decode_text_parameter(domain_oid, b"-1", &arena, 0)
        .unwrap_err();
    assert_eq!(invalid_text_domain.sqlstate, sqlstate::CHECK_VIOLATION);
    let invalid_enum = engine
        .decode_binary_parameter(enum_oid, b"missing", &arena, 0)
        .unwrap_err();
    assert_eq!(invalid_enum.sqlstate, sqlstate::INVALID_TEXT_REPRESENTATION);
    let invalid_domain = engine
        .decode_binary_parameter(domain_oid, &(-1_i32).to_be_bytes(), &arena, 0)
        .unwrap_err();
    assert_eq!(invalid_domain.sqlstate, sqlstate::CHECK_VIOLATION);
    for (oid, bytes) in [
        (crate::sql::types::oid::JSON, b"{not json}".as_slice()),
        (crate::sql::types::oid::JSONB, b"\x01{not json}".as_slice()),
    ] {
        let error = engine
            .decode_binary_parameter(oid, bytes, &arena, 0)
            .unwrap_err();
        assert_eq!(error.sqlstate, sqlstate::INVALID_TEXT_REPRESENTATION);
    }
    let required_domain_oid = crate::sql::types::oid::domain_oid(
        engine
            .storage
            .domain_slot("public", "binary_required", 0)
            .unwrap() as u16,
    );
    let null_domain = engine
        .coerce_parameter_null(required_domain_oid, &arena, 0)
        .unwrap_err();
    assert_eq!(null_domain.sqlstate, sqlstate::NOT_NULL_VIOLATION);

    let required_domain_array_oid = crate::sql::types::oid::domain_array_oid(
        engine
            .storage
            .domain_slot("public", "binary_required", 0)
            .unwrap() as u16,
    );
    let required_domain_array = [
        0,
        0,
        0,
        1, // dimensions
        0,
        0,
        0,
        1, // has NULL
        required_domain_oid.to_be_bytes()[0],
        required_domain_oid.to_be_bytes()[1],
        required_domain_oid.to_be_bytes()[2],
        required_domain_oid.to_be_bytes()[3],
        0,
        0,
        0,
        1, // length
        0,
        0,
        0,
        1, // lower bound
        0xff,
        0xff,
        0xff,
        0xff, // NULL element
    ];
    let null_domain_array = engine
        .decode_binary_parameter(required_domain_array_oid, &required_domain_array, &arena, 0)
        .unwrap_err();
    assert_eq!(null_domain_array.sqlstate, sqlstate::NOT_NULL_VIOLATION);

    let mut enum_array = Vec::new();
    enum_array.extend_from_slice(&1_i32.to_be_bytes());
    enum_array.extend_from_slice(&0_i32.to_be_bytes());
    enum_array.extend_from_slice(&enum_oid.to_be_bytes());
    enum_array.extend_from_slice(&2_i32.to_be_bytes());
    enum_array.extend_from_slice(&1_i32.to_be_bytes());
    for value in [b"ready".as_slice(), b"blocked".as_slice()] {
        enum_array.extend_from_slice(&(value.len() as i32).to_be_bytes());
        enum_array.extend_from_slice(value);
    }
    assert_eq!(
        engine
            .decode_binary_parameter(
                crate::sql::types::oid::enum_array_oid(
                    engine
                        .storage
                        .enum_slot("public", "binary_state", 0)
                        .unwrap() as u16,
                ),
                &enum_array,
                &arena,
                0,
            )
            .unwrap()
            .to_string(),
        "{ready,blocked}"
    );
    assert_eq!(
        engine
            .decode_text_parameter(
                crate::sql::types::oid::enum_array_oid(
                    engine
                        .storage
                        .enum_slot("public", "binary_state", 0)
                        .unwrap() as u16,
                ),
                b"{ready,blocked}",
                &arena,
                0,
            )
            .unwrap()
            .to_string(),
        "{ready,blocked}"
    );

    let mut domain_array = Vec::new();
    domain_array.extend_from_slice(&1_i32.to_be_bytes());
    domain_array.extend_from_slice(&0_i32.to_be_bytes());
    domain_array.extend_from_slice(&domain_oid.to_be_bytes());
    domain_array.extend_from_slice(&2_i32.to_be_bytes());
    domain_array.extend_from_slice(&1_i32.to_be_bytes());
    for value in [3_i32, 5_i32] {
        domain_array.extend_from_slice(&4_i32.to_be_bytes());
        domain_array.extend_from_slice(&value.to_be_bytes());
    }
    assert_eq!(
        engine
            .decode_binary_parameter(
                crate::sql::types::oid::domain_array_oid(
                    engine
                        .storage
                        .domain_slot("public", "binary_positive", 0)
                        .unwrap() as u16,
                ),
                &domain_array,
                &arena,
                0,
            )
            .unwrap()
            .to_string(),
        "{3,5}"
    );
    assert_eq!(
        engine
            .decode_text_parameter(
                crate::sql::types::oid::domain_array_oid(
                    engine
                        .storage
                        .domain_slot("public", "binary_positive", 0)
                        .unwrap() as u16,
                ),
                b"{3,5}",
                &arena,
                0,
            )
            .unwrap()
            .to_string(),
        "{3,5}"
    );
    let invalid_text_domain_array = engine
        .decode_text_parameter(
            crate::sql::types::oid::domain_array_oid(
                engine
                    .storage
                    .domain_slot("public", "binary_positive", 0)
                    .unwrap() as u16,
            ),
            b"{3,-1}",
            &arena,
            0,
        )
        .unwrap_err();
    assert_eq!(
        invalid_text_domain_array.sqlstate,
        sqlstate::CHECK_VIOLATION
    );
    let mut bit_array = Vec::new();
    bit_array.extend_from_slice(&1_i32.to_be_bytes());
    bit_array.extend_from_slice(&1_i32.to_be_bytes());
    bit_array.extend_from_slice(&crate::sql::types::oid::BIT.to_be_bytes());
    bit_array.extend_from_slice(&3_i32.to_be_bytes());
    bit_array.extend_from_slice(&1_i32.to_be_bytes());
    for value in [
        &[0, 0, 0, 5, 0b1011_0000][..],
        &[0, 0, 0, 5, 0b0011_1000][..],
    ] {
        bit_array.extend_from_slice(&(value.len() as i32).to_be_bytes());
        bit_array.extend_from_slice(value);
    }
    bit_array.extend_from_slice(&(-1_i32).to_be_bytes());
    assert_eq!(
        engine
            .decode_binary_parameter(crate::sql::types::oid::BIT_ARRAY, &bit_array, &arena, 0)
            .unwrap()
            .to_string(),
        "{10110,00111,NULL}"
    );
    bit_array[8..12].copy_from_slice(&crate::sql::types::oid::VARBIT.to_be_bytes());
    assert_eq!(
        engine
            .decode_binary_parameter(crate::sql::types::oid::VARBIT_ARRAY, &bit_array, &arena, 0)
            .unwrap()
            .to_string(),
        "{10110,00111,NULL}"
    );
    domain_array[8..12].copy_from_slice(&crate::sql::types::oid::INT4.to_be_bytes());
    let wrong_element_oid = engine
        .decode_binary_parameter(
            crate::sql::types::oid::domain_array_oid(
                engine
                    .storage
                    .domain_slot("public", "binary_positive", 0)
                    .unwrap() as u16,
            ),
            &domain_array,
            &arena,
            0,
        )
        .unwrap_err();
    assert_eq!(
        wrong_element_oid.sqlstate,
        sqlstate::INVALID_BINARY_REPRESENTATION
    );
    domain_array[8..12].copy_from_slice(&domain_oid.to_be_bytes());

    let malformed_array = [
        0, 0, 0, 1, // one dimension
        0, 0, 0, 1, // has nulls
        0, 0, 0, 23, // int4 element
        0, 0, 0, 1, // dimension size
        0, 0, 0, 1, // lower bound
        0xff, 0xff, 0xff, 0xfe, // only -1 is a NULL field length
    ];
    let malformed_array = engine
        .decode_binary_parameter(
            crate::sql::types::ColType::Array(crate::sql::types::ArrElem::Int4).oid(),
            &malformed_array,
            &arena,
            0,
        )
        .unwrap_err();
    assert_eq!(
        malformed_array.sqlstate,
        sqlstate::INVALID_BINARY_REPRESENTATION
    );

    let reserved_range_flags = engine
        .decode_binary_parameter(
            crate::sql::types::RangeKind::Int4.oid(),
            &[0x98], // reserved bit plus both infinity flags
            &arena,
            0,
        )
        .unwrap();
    assert_eq!(reserved_range_flags.to_string(), "(,)");
    let null_finite_range_bound = engine
        .decode_binary_parameter(
            crate::sql::types::RangeKind::Int4.oid(),
            &[0x00, 0xff, 0xff, 0xff, 0xff], // finite bound cannot be NULL
            &arena,
            0,
        )
        .unwrap_err();
    assert_eq!(
        null_finite_range_bound.sqlstate,
        sqlstate::INVALID_BINARY_REPRESENTATION
    );

    let mut record = Vec::new();
    record.extend_from_slice(&4_i32.to_be_bytes());
    for (field_oid, value) in [
        (enum_oid, b"ready".as_slice()),
        (domain_oid, &7_i32.to_be_bytes()),
        (
            crate::sql::types::oid::domain_array_oid(
                engine
                    .storage
                    .domain_slot("public", "binary_positive", 0)
                    .unwrap() as u16,
            ),
            domain_array.as_slice(),
        ),
        (crate::sql::types::oid::UNKNOWN, b"wire text".as_slice()),
    ] {
        record.extend_from_slice(&field_oid.to_be_bytes());
        record.extend_from_slice(&(value.len() as i32).to_be_bytes());
        record.extend_from_slice(value);
    }
    let record_value = engine
        .decode_binary_parameter(crate::sql::types::oid::RECORD, &record, &arena, 0)
        .unwrap();
    let Datum::Record(fields) = record_value else {
        panic!("binary record must decode as a record")
    };
    assert_eq!(
        fields
            .iter()
            .map(|field| field.value.to_string())
            .collect::<Vec<_>>(),
        ["ready", "7", "{3,5}", "wire text"]
    );
    let mut record_with_null_domain_array = Vec::new();
    record_with_null_domain_array.extend_from_slice(&1_i32.to_be_bytes());
    record_with_null_domain_array.extend_from_slice(&required_domain_array_oid.to_be_bytes());
    record_with_null_domain_array
        .extend_from_slice(&(required_domain_array.len() as i32).to_be_bytes());
    record_with_null_domain_array.extend_from_slice(&required_domain_array);
    assert_eq!(
        engine
            .decode_binary_parameter(
                crate::sql::types::oid::RECORD,
                &record_with_null_domain_array,
                &arena,
                0,
            )
            .unwrap_err()
            .sqlstate,
        sqlstate::NOT_NULL_VIOLATION
    );
    let direct_null_domain_record = [
        0,
        0,
        0,
        1, // field count
        required_domain_oid.to_be_bytes()[0],
        required_domain_oid.to_be_bytes()[1],
        required_domain_oid.to_be_bytes()[2],
        required_domain_oid.to_be_bytes()[3],
        0xff,
        0xff,
        0xff,
        0xff, // NULL domain field
    ];
    assert_eq!(
        engine
            .decode_binary_parameter(
                crate::sql::types::oid::RECORD,
                &direct_null_domain_record,
                &arena,
                0,
            )
            .unwrap_err()
            .sqlstate,
        sqlstate::NOT_NULL_VIOLATION
    );
    record[25..29].copy_from_slice(&(-1_i32).to_be_bytes());
    let invalid_record = engine
        .decode_binary_parameter(crate::sql::types::oid::RECORD, &record, &arena, 0)
        .unwrap_err();
    assert_eq!(invalid_record.sqlstate, sqlstate::CHECK_VIOLATION);
    let missing_type = engine
        .decode_binary_parameter(crate::sql::types::oid::enum_oid(31), b"ready", &arena, 0)
        .unwrap_err();
    assert_eq!(missing_type.sqlstate, sqlstate::UNDEFINED_OBJECT);
}

/// Like run_with but with a caller-owned TxnState, so explicit
/// transactions span calls (one call ≈ one wire message).
fn run_txn(engine: &mut Engine, budget: &mut Budget, txn: &mut TxnState, sql_text: &str) -> String {
    String::from_utf8_lossy(&run_txn_bytes(engine, budget, txn, sql_text)).to_string()
}

fn run_txn_bytes(
    engine: &mut Engine,
    budget: &mut Budget,
    txn: &mut TxnState,
    sql_text: &str,
) -> Vec<u8> {
    let mut buffer = crate::mem::FixedBuf::new(budget, "send", 1 << 18).unwrap();
    let arena = Arena::new(budget, "sql", 1 << 18).unwrap();
    let mut pool = test_pool(budget);
    let mut guc = GucState::new();
    let mut responder = Responder::new(&mut buffer);
    engine
        .execute_simple(
            sql_text,
            &arena,
            txn,
            &mut pool,
            &mut test_cursors(budget),
            &mut guc,
            &mut responder,
            1,
        )
        .unwrap();
    buffer.readable().to_vec()
}

