#[test]
fn rejected_slot_acknowledgement_does_not_reach_wal() {
    let (mut engine, _) = test_engine();
    let floor = engine
        .create_replication_slot(
            crate::storage::ReplicationSlotName::parse("changes").unwrap(),
            crate::storage::ReplicationSlotBehavior::DEFAULT,
        )
        .unwrap();
    let durable_lsn = engine.replication_identity().1;

    let error = engine
        .advance_replication_slot("changes", floor - 1)
        .unwrap_err();
    assert_eq!(error.sqlstate, sqlstate::INVALID_PARAMETER_VALUE);
    assert_eq!(engine.replication_identity().1, durable_lsn);

    let error = engine
        .advance_replication_slot("missing", floor)
        .unwrap_err();
    assert_eq!(error.sqlstate, sqlstate::UNDEFINED_OBJECT);
    assert_eq!(engine.replication_identity().1, durable_lsn);
}

fn logical_replication_publishes_truncate_only_with_pgoutput_v2_on_sized_stack() {
    let (mut engine, mut budget) = test_engine();
    let mut transaction = TxnState::new(&mut budget, 256).unwrap();
    run_txn(
        &mut engine,
        &mut budget,
        &mut transaction,
        "CREATE TABLE t (id int); CREATE PUBLICATION changes FOR TABLE t WITH (publish = 'truncate'); INSERT INTO t VALUES (1)",
    );
    let floor = engine.storage.lsn();
    run_txn(&mut engine, &mut budget, &mut transaction, "TRUNCATE t");

    let mut scratch =
        crate::mem::FixedBuf::new(&mut budget, "replication scratch", 1 << 16).unwrap();
    let mut send = crate::mem::FixedBuf::new(&mut budget, "replication send", 1 << 16).unwrap();
    let (lsn, emitted) = engine
        .emit_replication_transaction(
            floor,
            &[crate::storage::SqlName::parse("changes").unwrap()],
            false,
            crate::pg::pgoutput::ProtocolVersion::V2,
            &mut scratch,
            &mut Responder::new(&mut send),
        )
        .unwrap()
        .expect("truncate transaction is retained");
    assert!(emitted, "published truncate must emit pgoutput frames");
    assert!(lsn > floor);
    assert!(
        send.readable().windows(1).any(|bytes| bytes == b"T"),
        "pgoutput v2 must publish a truncate message"
    );

    let mut v1_scratch =
        crate::mem::FixedBuf::new(&mut budget, "v1 replication scratch", 1 << 16).unwrap();
    let mut v1_send =
        crate::mem::FixedBuf::new(&mut budget, "v1 replication send", 1 << 16).unwrap();
    let error = engine
        .emit_replication_transaction(
            floor,
            &[crate::storage::SqlName::parse("changes").unwrap()],
            false,
            crate::pg::pgoutput::ProtocolVersion::V1,
            &mut v1_scratch,
            &mut Responder::new(&mut v1_send),
        )
        .unwrap_err();
    assert_eq!(
        error.sqlstate,
        crate::sql::eval::sqlstate::FEATURE_NOT_SUPPORTED
    );
}

#[test]
fn explicit_rollback_discards_writes() {
    let (mut e, mut b) = test_engine();
    let mut t = TxnState::new(&mut b, 256).unwrap();
    run_txn(&mut e, &mut b, &mut t, "CREATE TABLE t (id int, v text)");
    run_txn(&mut e, &mut b, &mut t, "INSERT INTO t VALUES (1,'keep')");
    run_txn(&mut e, &mut b, &mut t, "BEGIN");
    assert_eq!(t.status_byte(), b'T');
    run_txn(&mut e, &mut b, &mut t, "INSERT INTO t VALUES (2,'discard')");
    run_txn(
        &mut e,
        &mut b,
        &mut t,
        "UPDATE t SET v = 'changed' WHERE id = 1",
    );
    run_txn(&mut e, &mut b, &mut t, "DELETE FROM t WHERE id = 1");
    // Inside the txn, the changes are visible to itself.
    let out = run_txn(&mut e, &mut b, &mut t, "SELECT count(*) FROM t");
    assert!(out.contains('1'), "{out}");
    run_txn(&mut e, &mut b, &mut t, "ROLLBACK");
    assert_eq!(t.status_byte(), b'I');
    let out = run_txn(&mut e, &mut b, &mut t, "SELECT id, v FROM t ORDER BY id");
    assert!(
        out.contains("keep") && !out.contains("discard") && !out.contains("changed"),
        "{out}"
    );
}

