#[test]
fn uncommitted_create_is_invisible_to_other_sessions() {
    let (mut e, mut b) = test_engine();
    let mut a = TxnState::new(&mut b, 256).unwrap();
    let mut s = TxnState::new(&mut b, 256).unwrap();
    run_txn(&mut e, &mut b, &mut a, "BEGIN");
    run_txn(&mut e, &mut b, &mut a, "CREATE TABLE t (id int)");
    run_txn(&mut e, &mut b, &mut a, "INSERT INTO t VALUES (1)");
    // The creator sees its own uncommitted table.
    let own = run_txn(&mut e, &mut b, &mut a, "SELECT id FROM t");
    assert!(
        own.contains("SELECT 1"),
        "creator sees its own table: {own}"
    );
    // Another session does not.
    let other = run_txn(&mut e, &mut b, &mut s, "SELECT id FROM t");
    assert!(
        other.contains("does not exist"),
        "other must not see it: {other}"
    );
    // Creating the same name waits for the owner, then rechecks the catalog.
    let conflict = run_txn(&mut e, &mut b, &mut s, "CREATE TABLE t (x int)");
    assert!(
        conflict.is_empty(),
        "concurrent create must park without output: {conflict}"
    );
    // After commit it becomes visible to everyone.
    run_txn(&mut e, &mut b, &mut a, "COMMIT");
    let resumed = run_txn(&mut e, &mut b, &mut s, "CREATE TABLE t (x int)");
    assert!(resumed.contains("42P07"), "{resumed}");
    let now = run_txn(&mut e, &mut b, &mut s, "SELECT id FROM t");
    assert!(now.contains("SELECT 1"), "visible after commit: {now}");
}

#[test]
fn uncommitted_drop_stays_visible_to_other_sessions() {
    let (mut e, mut b) = test_engine();
    let mut a = TxnState::new(&mut b, 256).unwrap();
    let mut s = TxnState::new(&mut b, 256).unwrap();
    run_txn(&mut e, &mut b, &mut a, "CREATE TABLE t (id int)");
    run_txn(&mut e, &mut b, &mut a, "INSERT INTO t VALUES (7)");
    run_txn(&mut e, &mut b, &mut a, "BEGIN");
    let dropped = run_txn(&mut e, &mut b, &mut a, "DROP TABLE t");
    assert!(dropped.contains("DROP TABLE"), "drop succeeds: {dropped}");
    // PostgreSQL keeps the old catalog image transactionally, but DROP's
    // ACCESS EXCLUSIVE lock makes a concurrent reader wait rather than use it.
    let other = run_txn(&mut e, &mut b, &mut s, "SELECT id FROM t");
    assert!(
        other.is_empty(),
        "concurrent SELECT waits for DROP TABLE: {other}"
    );
    run_txn(&mut e, &mut b, &mut a, "COMMIT");
    let after = run_txn(&mut e, &mut b, &mut s, "SELECT id FROM t");
    assert!(
        after.contains("does not exist"),
        "gone after commit: {after}"
    );
}

#[test]
fn transactional_alter_table_versions_shape_and_rows() {
    let (mut engine, mut budget) = test_engine();
    let mut owner = TxnState::new(&mut budget, 256).unwrap();
    let mut observer = TxnState::new(&mut budget, 256).unwrap();
    run_txn(
        &mut engine,
        &mut budget,
        &mut owner,
        "CREATE TABLE shaped (id int PRIMARY KEY, value text)",
    );
    run_txn(
        &mut engine,
        &mut budget,
        &mut owner,
        "INSERT INTO shaped VALUES (1, 'old')",
    );

    run_txn(&mut engine, &mut budget, &mut owner, "BEGIN");
    let altered = run_txn(
        &mut engine,
        &mut budget,
        &mut owner,
        "ALTER TABLE shaped ADD COLUMN generation int DEFAULT 7",
    );
    assert!(altered.contains("ALTER TABLE"), "{altered}");
    let owner_rows = data_rows(&run_with_txn_bytes(
        &mut engine,
        &mut budget,
        &mut owner,
        "SELECT id, value, generation FROM shaped",
    ));
    assert_eq!(owner_rows, ["1|old|7"]);
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut owner,
            "SELECT column_name FROM information_schema.columns \
             WHERE table_schema = 'public' AND table_name = 'shaped' \
             ORDER BY ordinal_position",
        )),
        ["id", "value", "generation"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut observer,
            "SELECT column_name FROM information_schema.columns \
             WHERE table_schema = 'public' AND table_name = 'shaped' \
             ORDER BY ordinal_position",
        )),
        ["id", "value"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut owner,
            "SELECT a.attname FROM pg_attribute a JOIN pg_class c \
             ON c.oid = a.attrelid WHERE c.relname = 'shaped' \
             ORDER BY a.attnum",
        )),
        ["id", "value", "generation"]
    );
    run_txn(
        &mut engine,
        &mut budget,
        &mut owner,
        "ALTER TABLE shaped ADD UNIQUE (generation)",
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut owner,
            "SELECT pg_get_constraintdef(c.oid, true) \
             FROM pg_constraint c JOIN pg_class r ON r.oid = c.conrelid \
             WHERE r.relname = 'shaped' AND c.conname = 'shaped_generation_key'",
        )),
        ["UNIQUE (generation)"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut observer,
            "SELECT count(*) FROM pg_constraint c JOIN pg_class r ON r.oid = c.conrelid \
             WHERE r.relname = 'shaped' AND c.conname = 'shaped_generation_key'",
        )),
        ["0"]
    );
    let observer_rows = run_with_txn_bytes(
        &mut engine,
        &mut budget,
        &mut observer,
        "SELECT id, value FROM shaped",
    );
    assert!(
        observer_rows.is_empty(),
        "observer waits for ALTER TABLE's ACCESS EXCLUSIVE lock"
    );

    run_txn(&mut engine, &mut budget, &mut owner, "ROLLBACK");
    let resumed_rows = data_rows(&run_with_txn_bytes(
        &mut engine,
        &mut budget,
        &mut observer,
        "SELECT id, value FROM shaped",
    ));
    assert_eq!(resumed_rows, ["1|old"]);
    let rolled_back = run_txn(
        &mut engine,
        &mut budget,
        &mut observer,
        "SELECT generation FROM shaped",
    );
    assert!(rolled_back.contains("42703"), "{rolled_back}");

    run_txn(&mut engine, &mut budget, &mut owner, "BEGIN");
    run_txn(
        &mut engine,
        &mut budget,
        &mut owner,
        "ALTER TABLE shaped ADD COLUMN generation int DEFAULT 9",
    );
    run_txn(
        &mut engine,
        &mut budget,
        &mut owner,
        "UPDATE shaped SET value = 'new', generation = 10 WHERE id = 1",
    );
    run_txn(&mut engine, &mut budget, &mut owner, "COMMIT");
    let committed = data_rows(&run_with_txn_bytes(
        &mut engine,
        &mut budget,
        &mut observer,
        "SELECT id, value, generation FROM shaped",
    ));
    assert_eq!(committed, ["1|new|10"]);
}

#[test]
fn information_schema_columns_describes_views_from_their_bound_row_type() {
    let (mut engine, mut budget) = test_engine();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE DOMAIN view_column_domain AS integer CHECK (VALUE > 0); \
         CREATE TYPE view_column_enum AS ENUM ('ready'); \
         CREATE TYPE view_column_coordinate AS (x integer, y integer); \
         CREATE DOMAIN view_column_coordinate_domain AS view_column_coordinate; \
         CREATE VIEW view_column_catalog AS \
           SELECT 1::view_column_domain AS domain_value, \
                  'ready'::view_column_enum AS enum_value, \
                  ARRAY[1] AS array_value, \
                  ROW(1, 2)::view_column_coordinate_domain AS composite_value, \
                  ARRAY[ROW(3, 4)::view_column_coordinate_domain] AS composite_values",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT column_name, ordinal_position, is_nullable, data_type \
             FROM information_schema.columns \
             WHERE table_name = 'view_column_catalog' \
             ORDER BY ordinal_position",
        )),
        [
            "domain_value|1|YES|integer",
            "enum_value|2|YES|USER-DEFINED",
            "array_value|3|YES|ARRAY",
            "composite_value|4|YES|USER-DEFINED",
            "composite_values|5|YES|ARRAY",
        ]
    );
    let domain_dependencies = data_rows(&run_with(
        &mut engine,
        &mut budget,
        "SELECT objid, refobjid FROM pg_depend WHERE refobjid = 230000",
    ));
    assert_eq!(
        domain_dependencies,
        ["110001|230000"],
        "domain type dependencies: {domain_dependencies:?}"
    );
    let mut owner = TxnState::new(&mut budget, 256).unwrap();
    let mut observer = TxnState::new(&mut budget, 256).unwrap();
    run_txn(&mut engine, &mut budget, &mut owner, "BEGIN");
    run_txn(
        &mut engine,
        &mut budget,
        &mut owner,
        "CREATE SCHEMA pending_view_schema",
    );
    run_txn(
        &mut engine,
        &mut budget,
        &mut owner,
        "CREATE TABLE pending_view_schema.pending_view_source (value integer); \
         CREATE VIEW pending_view_schema.pending_view_column_catalog AS \
           SELECT value FROM pending_view_schema.pending_view_source",
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut owner,
            "SELECT column_name FROM information_schema.columns \
             WHERE table_schema = 'pending_view_schema' \
               AND table_name = 'pending_view_column_catalog'",
        )),
        ["value"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut owner,
            "SELECT table_type FROM information_schema.tables \
             WHERE table_schema = 'pending_view_schema' \
               AND table_name = 'pending_view_column_catalog'",
        )),
        ["VIEW"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut observer,
            "SELECT count(*) FROM information_schema.columns \
             WHERE table_schema = 'pending_view_schema' \
               AND table_name = 'pending_view_column_catalog'",
        )),
        ["0"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut observer,
            "SELECT count(*) FROM information_schema.tables \
             WHERE table_schema = 'pending_view_schema' \
               AND table_name = 'pending_view_column_catalog'",
        )),
        ["0"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut owner,
            "SELECT schema_name FROM information_schema.schemata \
             WHERE schema_name = 'pending_view_schema'",
        )),
        ["pending_view_schema"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut owner,
            "SELECT schema_owner, default_character_set_catalog, \
                    default_character_set_schema, default_character_set_name, sql_path \
             FROM information_schema.schemata \
             WHERE schema_name = 'pending_view_schema'",
        )),
        ["postgres|NULL|NULL|NULL|NULL"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut owner,
            "SELECT nspname FROM pg_namespace WHERE nspname = 'pending_view_schema'; \
             SELECT typname FROM pg_type WHERE typname = 'pending_view_column_catalog'; \
             SELECT has_schema_privilege(oid, 'USAGE') FROM pg_namespace \
              WHERE nspname = 'pending_view_schema'",
        )),
        ["pending_view_schema", "pending_view_column_catalog", "t"]
    );
    assert_eq!(
        data_rows(&run_with_txn_bytes(
            &mut engine,
            &mut budget,
            &mut observer,
            "SELECT count(*) FROM information_schema.schemata \
             WHERE schema_name = 'pending_view_schema'",
        )),
        ["0"]
    );
    run_txn(&mut engine, &mut budget, &mut owner, "ROLLBACK");
}

#[test]
fn information_schema_columns_exposes_complete_column_metadata() {
    let (mut engine, mut budget) = test_engine();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE DOMAIN information_schema_column_domain AS varchar(7); \
         CREATE TYPE information_schema_column_enum AS ENUM ('ready'); \
         CREATE TABLE information_schema_column_metadata (\
           code varchar(12) NOT NULL DEFAULT 'new', \
           amount numeric(9,3), \
           occurred timestamp(2), \
           generated integer GENERATED ALWAYS AS (amount::integer + 1) STORED, \
           identity bigint GENERATED BY DEFAULT AS IDENTITY, \
           domain_value information_schema_column_domain, \
           enum_value information_schema_column_enum)",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT column_name, character_maximum_length, numeric_precision, \
                    numeric_precision_radix, numeric_scale, datetime_precision, \
                    data_type, domain_name, udt_schema, udt_name, is_identity, \
                    identity_generation, identity_maximum, identity_minimum, \
                    identity_cycle, is_generated, dtd_identifier, is_updatable \
             FROM information_schema.columns \
             WHERE table_name = 'information_schema_column_metadata' \
             ORDER BY ordinal_position",
        )),
        [
            "code|12|NULL|NULL|NULL|NULL|character varying|NULL|pg_catalog|varchar|NO|NULL|NULL|NULL|NO|NEVER|1|YES",
            "amount|NULL|9|10|3|NULL|numeric|NULL|pg_catalog|numeric|NO|NULL|NULL|NULL|NO|NEVER|2|YES",
            "occurred|NULL|NULL|NULL|NULL|2|timestamp without time zone|NULL|pg_catalog|timestamp|NO|NULL|NULL|NULL|NO|NEVER|3|YES",
            "generated|NULL|32|2|0|NULL|integer|NULL|pg_catalog|int4|NO|NULL|NULL|NULL|NO|ALWAYS|4|YES",
            "identity|NULL|64|2|0|NULL|bigint|NULL|pg_catalog|int8|YES|BY DEFAULT|9223372036854775807|1|NO|NEVER|5|YES",
            "domain_value|7|NULL|NULL|NULL|NULL|character varying|information_schema_column_domain|public|information_schema_column_domain|NO|NULL|NULL|NULL|NO|NEVER|6|YES",
            "enum_value|NULL|NULL|NULL|NULL|NULL|USER-DEFINED|NULL|public|information_schema_column_enum|NO|NULL|NULL|NULL|NO|NEVER|7|YES",
        ]
    );
    run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE information_schema_identity_options (\
           value integer GENERATED BY DEFAULT AS IDENTITY \
             (START WITH 7 INCREMENT BY 3 MINVALUE 4 MAXVALUE 40 CYCLE))",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT identity_start, identity_increment, identity_maximum, \
                    identity_minimum, identity_cycle \
             FROM information_schema.columns \
             WHERE table_name = 'information_schema_identity_options'",
        )),
        ["7|3|40|4|YES"]
    );
}

