#[test]
fn indexes_survive_restart() {
    // Indexes (and their UNIQUE constraint) are journaled and survive a
    // WAL-replay restart.
    let config = test_config("idx_restart");
    {
        let mut budget = Budget::new(1 << 26);
        let mut e = Engine::new(&config, &mut budget).unwrap();
        run_with(&mut e, &mut budget, "CREATE TABLE t (a int, b int)");
        run_with(&mut e, &mut budget, "INSERT INTO t VALUES (1,1),(1,2)");
        run_with(
            &mut e,
            &mut budget,
            "CREATE UNIQUE INDEX u ON t(a DESC NULLS LAST,b ASC NULLS FIRST)",
        );
        e.commit_wal().unwrap();
    }
    let mut budget = Budget::new(1 << 26);
    let mut e = Engine::new(&config, &mut budget).unwrap();
    assert_eq!(
        data_rows(&run_with(
            &mut e,
            &mut budget,
            "SELECT indexdef FROM pg_indexes WHERE indexname = 'u'"
        )),
        ["CREATE UNIQUE INDEX u ON public.t USING btree (a DESC NULLS LAST, b NULLS FIRST)"]
    );
    // The UNIQUE index survived: a conflicting insert is rejected.
    assert!(
        String::from_utf8_lossy(&run_with(&mut e, &mut budget, "INSERT INTO t VALUES (1,1)"))
            .contains("23505")
    );
    // A non-conflicting insert works.
    let out = String::from_utf8_lossy(&run_with(&mut e, &mut budget, "INSERT INTO t VALUES (3,3)"))
        .to_string();
    assert!(!out.contains("23505"), "{out}");
}

#[test]
fn views_survive_restart() {
    // View definitions are journaled, so they survive a WAL-replay restart.
    let config = test_config("view_restart");
    {
        let mut budget = Budget::new(1 << 26);
        let mut e = Engine::new(&config, &mut budget).unwrap();
        run_with(&mut e, &mut budget, "CREATE TABLE t (id int, v int)");
        run_with(
            &mut e,
            &mut budget,
            "INSERT INTO t VALUES (1,10),(2,20),(3,30)",
        );
        run_with(
            &mut e,
            &mut budget,
            "CREATE VIEW big AS SELECT id FROM t WHERE v > 15",
        );
        run_with(&mut e, &mut budget, "CREATE VIEW gone AS SELECT 1");
        run_with(&mut e, &mut budget, "DROP VIEW gone");
        e.commit_wal().unwrap();
    }
    let mut budget = Budget::new(1 << 26);
    let mut e = Engine::new(&config, &mut budget).unwrap();
    // The surviving view still expands and queries.
    assert_eq!(
        data_rows(&run_with(
            &mut e,
            &mut budget,
            "SELECT id FROM big ORDER BY id"
        )),
        ["2", "3"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut e,
            &mut budget,
            "SELECT column_name FROM information_schema.view_column_usage \
             WHERE view_name = 'big' ORDER BY column_name",
        )),
        ["id", "v"]
    );
    // The dropped view is gone.
    assert!(
        String::from_utf8_lossy(&run_with(&mut e, &mut budget, "SELECT * FROM gone"))
            .contains("42P01")
    );
}

#[test]
fn sql_routine_lifecycle_is_transactional_and_durable() {
    let mut config = test_config("routine_lifecycle");
    config.max_tables = 16;
    let answer_oid: i32;
    {
        let mut budget = Budget::new(1 << 29);
        let mut engine = Engine::new(&config, &mut budget).unwrap();
        let mut guc = GucState::new();
        let mut transaction = TxnState::new(&mut budget, 1024).unwrap();
        macro_rules! execute {
            ($sql:expr) => {
                run_session_transaction(&mut engine, &mut budget, &mut transaction, &mut guc, $sql)
            };
        }
        let created = run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION answer() RETURNS integer LANGUAGE SQL AS 'SELECT 42'",
        );
        assert!(!String::from_utf8_lossy(&created).contains("ERROR"));
        let listed = run_with(
            &mut engine,
            &mut budget,
            "SELECT proname, pronargs FROM pg_proc WHERE proname = 'answer'",
        );
        assert_eq!(
            data_rows(&listed),
            ["answer|0"],
            "{}",
            String::from_utf8_lossy(&listed)
        );
        let answer = run_with(&mut engine, &mut budget, "SELECT answer()");
        assert_eq!(
            data_rows(&answer),
            ["42"],
            "{}",
            String::from_utf8_lossy(&answer)
        );
        assert_eq!(
            row_description_type_oids(&describe_with(&mut engine, &mut budget, "SELECT answer()")),
            [23]
        );
        run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION increment(integer) RETURNS integer LANGUAGE SQL AS 'SELECT $1 + 1'",
        );
        assert_eq!(
            data_rows(&run_with(&mut engine, &mut budget, "SELECT increment(41)")),
            ["42"]
        );
        run_with(
            &mut engine,
            &mut budget,
            "CREATE TABLE routine_lookup (id integer PRIMARY KEY, value integer);
             INSERT INTO routine_lookup VALUES (1, 40), (2, 41);
             CREATE FUNCTION lookup_routine_value(integer) RETURNS integer LANGUAGE SQL
               AS 'SELECT value FROM routine_lookup WHERE id = $1';
             CREATE FUNCTION nested_routine_value(integer) RETURNS integer LANGUAGE SQL
               AS 'SELECT lookup_routine_value($1) + 1';
             CREATE FUNCTION routine_values_from(integer) RETURNS SETOF integer LANGUAGE SQL
               AS 'SELECT value FROM routine_lookup WHERE id >= $1';
             CREATE FUNCTION routine_pairs_from(integer) RETURNS TABLE (routine_id integer, routine_value integer) LANGUAGE SQL
               AS 'SELECT id, value FROM routine_lookup WHERE id >= $1'",
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT lookup_routine_value(1), nested_routine_value(2)",
            )),
            ["40|42"]
        );
        let multi_query_created = run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION multi_query_value(integer) RETURNS integer LANGUAGE SQL \
               AS 'SELECT 1 / $1 UNION ALL SELECT 2 / $1; \
                   INSERT INTO routine_lookup VALUES (3, $1); \
                   WITH inserted_value AS (SELECT value FROM routine_lookup WHERE id = 3) \
                   SELECT value + 2 FROM inserted_value'",
        );
        assert!(
            !String::from_utf8_lossy(&multi_query_created).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&multi_query_created)
        );
        let multi_query_pairs_created = run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION multi_query_pairs(integer) RETURNS TABLE (routine_id integer, routine_value integer) LANGUAGE SQL \
               AS 'SELECT $1; WITH first_pair AS (SELECT $1 AS value), \
                        derived_pair AS (SELECT value, value + 1 AS next_value FROM first_pair) \
                   SELECT value, next_value FROM derived_pair UNION ALL SELECT $1 + 1, $1 + 2'",
        );
        assert!(
            !String::from_utf8_lossy(&multi_query_pairs_created).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&multi_query_pairs_created)
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT multi_query_value(40)",
            )),
            ["42"]
        );
        run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION update_routine_value(integer) RETURNS integer LANGUAGE SQL \
               AS 'UPDATE routine_lookup SET value = value + $1 WHERE id = 1 RETURNING value'; \
             CREATE FUNCTION delete_routine_value() RETURNS integer LANGUAGE SQL \
               AS 'DELETE FROM routine_lookup WHERE id = 2 RETURNING value'",
        );
        let returned_writes = run_with(
            &mut engine,
            &mut budget,
            "BEGIN; SELECT update_routine_value(2); SELECT delete_routine_value(); ROLLBACK",
        );
        assert_eq!(
            data_rows(&returned_writes),
            ["42", "41"],
            "{}",
            String::from_utf8_lossy(&returned_writes)
        );
        run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION update_all_routine_values() RETURNS integer LANGUAGE SQL \
               AS 'UPDATE routine_lookup SET value = value + 1 RETURNING value'",
        );
        let complete_dml_result = run_with(
            &mut engine,
            &mut budget,
            "BEGIN; \
             SELECT update_all_routine_values(); \
             SELECT value FROM routine_lookup ORDER BY id; \
             ROLLBACK",
        );
        assert_eq!(
            data_rows(&complete_dml_result),
            ["41", "41", "42", "41"],
            "{}",
            String::from_utf8_lossy(&complete_dml_result)
        );
        run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION clean_routine_value() RETURNS void LANGUAGE SQL \
               AS 'DELETE FROM routine_lookup WHERE id = 2'",
        );
        assert_eq!(
            row_description_type_oids(&describe_with(
                &mut engine,
                &mut budget,
                "SELECT clean_routine_value()",
            )),
            [crate::sql::types::oid::VOID]
        );
        let void_result = run_with(
            &mut engine,
            &mut budget,
            "BEGIN; SELECT clean_routine_value(); \
             SELECT count(*) FROM routine_lookup; ROLLBACK",
        );
        assert_eq!(
            data_rows(&void_result),
            ["NULL", "2"],
            "{}",
            String::from_utf8_lossy(&void_result)
        );
        let void_column = run_with(
            &mut engine,
            &mut budget,
            "CREATE TABLE invalid_void (value void)",
        );
        assert!(
            String::from_utf8_lossy(&void_column).contains("42P16"),
            "{}",
            String::from_utf8_lossy(&void_column)
        );
        let void_transaction_control = run_with(
            &mut engine,
            &mut budget,
            "CREATE OR REPLACE FUNCTION clean_routine_value() RETURNS void LANGUAGE SQL \
               AS 'SAVEPOINT function_savepoint'; \
             SELECT clean_routine_value()",
        );
        assert!(
            String::from_utf8_lossy(&void_transaction_control).contains("25001"),
            "{}",
            String::from_utf8_lossy(&void_transaction_control)
        );
        let utility_prelude = run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION create_routine_table() RETURNS integer LANGUAGE SQL \
               AS 'CREATE TABLE routine_created_in_function (value integer); SELECT 44'; \
             SELECT create_routine_table(); \
             INSERT INTO routine_created_in_function VALUES (45); \
             SELECT value FROM routine_created_in_function",
        );
        assert_eq!(
            data_rows(&utility_prelude),
            ["44", "45"],
            "{}",
            String::from_utf8_lossy(&utility_prelude)
        );
        let transaction_control = run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION transaction_control_in_function() RETURNS integer LANGUAGE SQL \
               AS 'SAVEPOINT function_savepoint; SELECT 1'; \
             SELECT transaction_control_in_function()",
        );
        assert!(
            String::from_utf8_lossy(&transaction_control).contains("25001"),
            "{}",
            String::from_utf8_lossy(&transaction_control)
        );
        let vacuum_in_function = run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION vacuum_in_function() RETURNS integer LANGUAGE SQL \
               AS 'VACUUM routine_lookup; SELECT 1'; \
             SELECT vacuum_in_function()",
        );
        assert!(
            String::from_utf8_lossy(&vacuum_in_function).contains("25001"),
            "{}",
            String::from_utf8_lossy(&vacuum_in_function)
        );
        let on_path = execute!(
            "CREATE SCHEMA routine_path; \
             SET search_path TO routine_path, public; \
             CREATE FUNCTION write_on_path(integer) RETURNS integer LANGUAGE SQL \
               AS 'INSERT INTO public.routine_lookup VALUES (4, $1); \
                   WITH inserted_value AS (SELECT value FROM public.routine_lookup WHERE id = 4) \
                   SELECT value + 2 FROM inserted_value'; \
             CREATE FUNCTION table_on_path(integer) RETURNS TABLE (result integer) LANGUAGE SQL \
               AS 'SELECT $1'; \
             CREATE PROCEDURE procedure_on_path(integer) LANGUAGE SQL \
               AS 'INSERT INTO public.routine_lookup VALUES (5, $1)'; \
             SELECT write_on_path(60); \
             SELECT result FROM table_on_path(61); \
             CALL procedure_on_path(62); \
             SET search_path TO public"
        );
        assert_eq!(
            data_rows(&on_path),
            ["62", "61"],
            "{}",
            String::from_utf8_lossy(&on_path)
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT routine_id, routine_value FROM multi_query_pairs(7) ORDER BY routine_id",
            )),
            ["7|8", "8|9"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT id, value FROM routine_lookup WHERE id IN (3, 4, 5) ORDER BY id",
            )),
            ["3|40", "4|60", "5|62"]
        );
        run_with(
            &mut engine,
            &mut budget,
            "DELETE FROM routine_lookup WHERE id IN (3, 4, 5)",
        );
        let rolled_back = run_with(
            &mut engine,
            &mut budget,
            "BEGIN; \
             SELECT multi_query_value(50); \
             ROLLBACK; \
             SELECT count(*) FROM routine_lookup WHERE id = 3",
        );
        assert_eq!(
            data_rows(&rolled_back),
            ["52", "0"],
            "{}",
            String::from_utf8_lossy(&rolled_back)
        );
        let leading_query_error = run_with(&mut engine, &mut budget, "SELECT multi_query_value(0)");
        assert!(
            String::from_utf8_lossy(&leading_query_error).contains("22012"),
            "{}",
            String::from_utf8_lossy(&leading_query_error)
        );
        run_with(
            &mut engine,
            &mut budget,
            "DELETE FROM routine_lookup WHERE id IN (3, 4, 5); \
             DROP FUNCTION create_routine_table(); DROP FUNCTION update_all_routine_values(); \
             DROP FUNCTION clean_routine_value(); \
             DROP TABLE routine_created_in_function; \
             DROP FUNCTION multi_query_value(integer); DROP FUNCTION multi_query_pairs(integer); \
             DROP FUNCTION routine_path.write_on_path(integer); \
             DROP FUNCTION routine_path.table_on_path(integer); \
             DROP PROCEDURE routine_path.procedure_on_path(integer); \
             DROP SCHEMA routine_path",
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT value FROM routine_values_from(1) AS values_from(value) ORDER BY value",
            )),
            ["40", "41"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT routine_id, routine_value FROM routine_pairs_from(1) ORDER BY routine_id",
            )),
            ["1|40", "2|41"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT lookup.id, pairs.routine_value \
                 FROM routine_lookup AS lookup \
                 JOIN LATERAL routine_pairs_from(lookup.id) AS pairs ON true \
                 ORDER BY lookup.id, pairs.routine_value",
            )),
            ["1|40", "1|41", "2|41"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT routine_id, routine_value, ordinality \
                 FROM routine_pairs_from(1) WITH ORDINALITY \
                 ORDER BY ordinality",
            )),
            ["1|40|1", "2|41|2"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT lookup.id, values_from.value \
                 FROM routine_lookup AS lookup \
                 JOIN LATERAL routine_values_from(lookup.id) AS values_from(value) ON true \
                 ORDER BY lookup.id, values_from.value",
            )),
            ["1|40", "1|41", "2|41"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT value, ordinality \
                 FROM routine_values_from(1) WITH ORDINALITY AS values_from(value, ordinality) \
                 ORDER BY ordinality",
            )),
            ["40|1", "41|2"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT proretset, pg_get_functiondef(oid) \
                 FROM pg_proc WHERE proname = 'routine_values_from'",
            )),
            [
                "t|CREATE OR REPLACE FUNCTION public.routine_values_from(integer) RETURNS SETOF integer LANGUAGE sql AS 'SELECT value FROM routine_lookup WHERE id >= $1'"
            ],
        );
        let changed_set_contract = run_with(
            &mut engine,
            &mut budget,
            "CREATE OR REPLACE FUNCTION routine_values_from(integer) RETURNS integer LANGUAGE SQL \
             AS 'SELECT value FROM routine_lookup WHERE id >= $1'",
        );
        assert!(
            String::from_utf8_lossy(&changed_set_contract).contains("42P13"),
            "{}",
            String::from_utf8_lossy(&changed_set_contract)
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT proretset, prorettype, pg_get_functiondef(oid) \
                 FROM pg_proc WHERE proname = 'routine_pairs_from'",
            )),
            [
                "t|2249|CREATE OR REPLACE FUNCTION public.routine_pairs_from(integer) RETURNS TABLE (routine_id integer, routine_value integer) LANGUAGE sql AS 'SELECT id, value FROM routine_lookup WHERE id >= $1'"
            ]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT pg_get_function_arguments(oid), pg_get_function_identity_arguments(oid), pg_get_function_result(oid) FROM pg_proc WHERE proname = 'routine_pairs_from'"
            )),
            ["integer|integer|TABLE(routine_id integer, routine_value integer)"]
        );
        let changed_table_contract = run_with(
            &mut engine,
            &mut budget,
            "CREATE OR REPLACE FUNCTION routine_pairs_from(integer) RETURNS TABLE (routine_id integer, routine_value text) LANGUAGE SQL \
             AS 'SELECT id, value FROM routine_lookup WHERE id >= $1'",
        );
        assert!(
            String::from_utf8_lossy(&changed_table_contract).contains("42P13"),
            "{}",
            String::from_utf8_lossy(&changed_table_contract)
        );
        let duplicate_table_columns = run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION duplicate_table_columns() RETURNS TABLE (value integer, value text) LANGUAGE SQL AS 'SELECT 1, 2'",
        );
        assert!(
            String::from_utf8_lossy(&duplicate_table_columns).contains("42P13"),
            "{}",
            String::from_utf8_lossy(&duplicate_table_columns)
        );
        run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION ambiguous_routine_value() RETURNS integer LANGUAGE SQL
               AS 'SELECT value FROM routine_lookup'",
        );
        let first_row = run_with(&mut engine, &mut budget, "SELECT ambiguous_routine_value()");
        assert!(
            data_rows(&first_row) == ["40"],
            "{}",
            String::from_utf8_lossy(&first_row)
        );
        run_with(
            &mut engine,
            &mut budget,
            "DROP FUNCTION ambiguous_routine_value()",
        );
        let invalid_body = run_with(
            &mut engine,
            &mut budget,
            "CREATE FUNCTION invalid_routine_body() RETURNS integer LANGUAGE SQL
               AS 'INSERT INTO routine_lookup VALUES (3, 42)'",
        );
        assert!(
            String::from_utf8_lossy(&invalid_body).contains("0A000"),
            "{}",
            String::from_utf8_lossy(&invalid_body)
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT routine_name, data_type FROM information_schema.routines WHERE routine_name = 'answer'",
            )),
            ["answer|integer"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT proname, pronargs, prorettype, prokind, proargtypes FROM pg_proc WHERE proname IN ('answer', 'increment') ORDER BY proname",
            )),
            ["answer|0|23|f|", "increment|1|23|f|23"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT parameter_name, data_type FROM information_schema.parameters WHERE specific_name LIKE 'increment_%'",
            )),
            ["NULL|integer"]
        );
        let oid = data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT oid FROM pg_proc WHERE proname = 'answer'",
        ))[0]
            .parse::<i32>()
            .unwrap();
        answer_oid = oid;
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                &format!("SELECT pg_function_is_visible({oid})"),
            )),
            ["t"]
        );
        let definition = data_rows(&run_with(
            &mut engine,
            &mut budget,
            &format!("SELECT pg_get_functiondef({oid})"),
        ));
        assert_eq!(
            definition,
            [
                "CREATE OR REPLACE FUNCTION public.answer() RETURNS integer LANGUAGE sql AS 'SELECT 42'"
            ]
        );

        execute!("BEGIN");
        execute!("CREATE OR REPLACE FUNCTION answer() RETURNS integer LANGUAGE SQL AS 'SELECT 43'");
        assert_eq!(data_rows(&execute!("SELECT answer()")), ["43"]);
        assert_eq!(
            data_rows(&run_with(&mut engine, &mut budget, "SELECT answer()")),
            ["42"],
            "a second transaction must retain the committed routine definition"
        );
        execute!("COMMIT");
        assert_eq!(data_rows(&execute!("SELECT answer()")), ["43"]);
        assert_eq!(
            data_rows(&execute!(
                "SELECT oid FROM pg_proc WHERE proname = 'answer'"
            )),
            [oid.to_string()]
        );

        execute!("CREATE ROLE routine_owner");
        execute!("GRANT CREATE ON SCHEMA public TO routine_owner");
        execute!("SET ROLE routine_owner");
        execute!("CREATE FUNCTION owned_answer() RETURNS integer LANGUAGE SQL AS 'SELECT 41'");
        execute!("RESET ROLE");
        let owned_replacement = execute!(
            "CREATE OR REPLACE FUNCTION owned_answer() RETURNS integer LANGUAGE SQL AS 'SELECT 44'"
        );
        assert!(
            !String::from_utf8_lossy(&owned_replacement).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&owned_replacement)
        );
        assert_eq!(
            data_rows(&execute!(
                "SELECT pg_get_userbyid(proowner), owned_answer() FROM pg_proc WHERE proname = 'owned_answer'"
            )),
            ["routine_owner|44"]
        );

        execute!("BEGIN");
        execute!("SAVEPOINT routine_drop");
        execute!("DROP FUNCTION answer()");
        let missing = execute!("SELECT answer()");
        assert!(String::from_utf8_lossy(&missing).contains("42883"));
        execute!("ROLLBACK TO SAVEPOINT routine_drop");
        assert_eq!(data_rows(&execute!("SELECT answer()")), ["43"]);
        execute!("COMMIT");
        engine.commit_wal().unwrap();
    }
    let mut budget = Budget::new(1 << 28);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    assert_eq!(
        data_rows(&run_with(&mut engine, &mut budget, "SELECT answer()")),
        ["43"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT value FROM routine_values_from(1) AS values_from(value) ORDER BY value",
        )),
        ["40", "41"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT routine_id, routine_value FROM routine_pairs_from(1) ORDER BY routine_id",
        )),
        ["1|40", "2|41"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT oid FROM pg_proc WHERE proname = 'answer'",
        )),
        [answer_oid.to_string()]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE proname = 'owned_answer'",
        )),
        ["routine_owner"]
    );
    run_with(&mut engine, &mut budget, "DROP FUNCTION answer()");
    engine.commit_wal().unwrap();
    drop(engine);
    let mut budget = Budget::new(1 << 28);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let missing = run_with(&mut engine, &mut budget, "SELECT answer()");
    assert!(String::from_utf8_lossy(&missing).contains("42883"));
}

#[test]
fn routine_parameter_contracts_drive_defaults_outputs_and_catalog_text() {
    let mut config = test_config("routine_parameter_contracts");
    config.object_store_on = true;
    config.object_store_sim = true;
    config.object_store_namespace = format!("routine-parameter-contracts-{}", std::process::id());
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    let mut budget = Budget::new(1 << 29);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let created = run_with(
        &mut engine,
        &mut budget,
        "CREATE FUNCTION f_defaults(a integer, b integer DEFAULT 2, c integer = 3) \
             RETURNS integer LANGUAGE SQL AS 'SELECT a + b + c';
         CREATE FUNCTION f_out(a integer, OUT doubled integer, OUT tripled integer) \
             LANGUAGE SQL AS 'SELECT a * 2, a * 3';
         CREATE FUNCTION f_variadic(prefix integer, VARIADIC vals integer[]) \
             RETURNS integer LANGUAGE SQL AS 'SELECT prefix + cardinality(vals)';
         CREATE FUNCTION f_named_rows(a integer, b integer DEFAULT 2) \
             RETURNS TABLE(total integer) LANGUAGE SQL AS 'SELECT a + b';
         CREATE FUNCTION f_variadic_rows(VARIADIC vals integer[]) \
             RETURNS TABLE(total integer) LANGUAGE SQL AS 'SELECT cardinality(vals)';
         CREATE TABLE procedure_log (a integer, b integer);
         CREATE PROCEDURE p_defaults(a integer, b integer DEFAULT 2) \
             LANGUAGE SQL AS 'INSERT INTO procedure_log VALUES (a, b)';
         CREATE PROCEDURE p_out(IN a integer, OUT doubled integer, INOUT total integer, \
                                IN b integer DEFAULT 2) \
             LANGUAGE SQL AS 'SELECT a * 2, total + b';
         CREATE PROCEDURE p_variadic(prefix integer, VARIADIC vals integer[]) \
             LANGUAGE SQL AS 'INSERT INTO procedure_log VALUES (prefix, cardinality(vals))';
         CALL p_defaults(3);
         CALL p_defaults(b => 5, a => 4);
         CALL p_variadic(7, 1, 2, 3);
         CALL p_variadic(8, VARIADIC ARRAY[4, 5]);",
    );
    assert!(
        !String::from_utf8_lossy(&created).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&created)
    );
    let output = run_with(
        &mut engine,
        &mut budget,
        "SELECT f_defaults(1), f_defaults(1, 10), f_defaults(1, 10, 20), \
                f_defaults(c => 30, a => 1, b => 10); \
         SELECT f_variadic(10, 1), f_variadic(10, 1, 2), \
                f_variadic(10, VARIADIC ARRAY[1, 2, 3]); \
         SELECT total FROM f_named_rows(b => 5, a => 3); \
         SELECT total FROM f_variadic_rows(1, 2, 3); \
         SELECT total FROM f_variadic_rows(VARIADIC ARRAY[1, 2]); \
         SELECT (f_out(4)).doubled, (f_out(4)).tripled; \
         SELECT pg_get_function_arguments('f_defaults(integer,integer,integer)'::regprocedure), \
                pg_get_function_identity_arguments('f_out(integer)'::regprocedure), \
                pg_get_function_result('f_out(integer)'::regprocedure); \
         SELECT pronargdefaults, provariadic, proallargtypes::text, proargmodes::text, \
                proargnames::text, proargdefaults::text, prosqlbody IS NULL \
           FROM pg_proc WHERE proname = 'f_defaults'; \
         SELECT pronargdefaults, provariadic, proallargtypes::text, proargmodes::text, \
                proargnames::text, proargdefaults IS NULL, prosqlbody IS NULL \
           FROM pg_proc WHERE proname = 'f_out'; \
         SELECT pronargdefaults, provariadic, proallargtypes::text, proargmodes::text, \
                proargnames::text \
           FROM pg_proc WHERE proname = 'f_variadic'; \
         CALL p_out(3, NULL, 10); \
         SELECT a, b FROM procedure_log ORDER BY a;",
    );
    assert_eq!(
        data_rows(&output),
        [
            "6|14|31|41",
            "11|12|13",
            "8",
            "3",
            "2",
            "8|12",
            "a integer, b integer DEFAULT 2, c integer DEFAULT 3|a integer, OUT doubled integer, OUT tripled integer|record",
            "2|0|NULL|NULL|{a,b,c}|2, 3|t",
            "0|0|{23,23,23}|{i,o,o}|{a,doubled,tripled}|t|t",
            "0|23|{23,1007}|{i,v}|{prefix,vals}",
            "6|12",
            "3|2",
            "4|5",
            "7|3",
            "8|2",
        ],
        "{}",
        String::from_utf8_lossy(&output)
    );
    assert_eq!(
        row_description_type_oids(&describe_with(
            &mut engine,
            &mut budget,
            "SELECT f_defaults(c => 30, a => 1, b => 10)",
        )),
        [23]
    );
    assert_eq!(
        row_description_type_oids(&describe_with(
            &mut engine,
            &mut budget,
            "CALL p_out(3, NULL, 10)",
        )),
        [23, 23]
    );
    let omitted_variadic = run_with(&mut engine, &mut budget, "SELECT f_variadic(10)");
    assert!(
        String::from_utf8_lossy(&omitted_variadic).contains("42883"),
        "{}",
        String::from_utf8_lossy(&omitted_variadic)
    );
    assert!(engine.checkpoint().unwrap());
    drop(engine);
    std::fs::remove_dir_all(&config.data_dir).unwrap();
    let mut budget = Budget::new(1 << 29);
    let mut recovered = Engine::new(&config, &mut budget).unwrap();
    let recovered_output = run_with(
        &mut recovered,
        &mut budget,
        "SELECT f_defaults(10), (f_out(5)).doubled, (f_out(5)).tripled; \
         SELECT f_variadic(20, 1, 2), f_variadic(20, VARIADIC ARRAY[1, 2, 3]); \
         SELECT total FROM f_named_rows(b => 7, a => 3); \
         SELECT total FROM f_variadic_rows(1, 2, 3, 4); \
         CALL p_out(4, 1 / 0, 20); \
         CALL p_variadic(9, 1, 2, 3, 4); \
         CALL p_defaults(6); \
         SELECT a, b FROM procedure_log ORDER BY a; \
         SELECT pg_get_function_arguments('f_defaults(integer,integer,integer)'::regprocedure);",
    );
    assert_eq!(
        data_rows(&recovered_output),
        [
            "15|10|15",
            "22|23",
            "10",
            "4",
            "8|22",
            "3|2",
            "4|5",
            "6|2",
            "7|3",
            "8|2",
            "9|4",
            "a integer, b integer DEFAULT 2, c integer DEFAULT 3",
        ],
        "{}",
        String::from_utf8_lossy(&recovered_output)
    );
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
}

#[test]
fn user_defined_aggregate_executes_typed_transition_final_and_ordering() {
    let mut config = test_config("user-defined-aggregate-execution");
    config.max_tables = 32;
    let mut budget = Budget::new(1 << 28);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let setup = run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE aggregate_input (g integer, v integer); \
         INSERT INTO aggregate_input VALUES (1, 3), (1, 1), (1, 2), (1, NULL), (2, 5); \
         CREATE FUNCTION aggregate_sum_state(state bigint, value integer) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT coalesce(state, 0) + coalesce(value, 0)'; \
         CREATE FUNCTION aggregate_double(state bigint) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT state * 2'; \
         CREATE FUNCTION aggregate_sum_inverse(state bigint, value integer) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT state - coalesce(value, 0)'; \
         CREATE FUNCTION aggregate_offset(state bigint, direct integer) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT state + direct'; \
         CREATE FUNCTION aggregate_concat_state(state text, value integer) \
           RETURNS text LANGUAGE SQL AS 'SELECT concat(state, value)'; \
         CREATE FUNCTION aggregate_strict_product(state integer, value integer) \
           RETURNS integer AS 'SELECT state * value' IMMUTABLE STRICT PARALLEL SAFE LANGUAGE SQL; \
         CREATE FUNCTION aggregate_strict_mismatch(state bigint, value integer) \
           RETURNS bigint LANGUAGE SQL STRICT AS 'SELECT state + value'; \
         CREATE FUNCTION aggregate_nonstrict_product_inverse(state integer, value integer) \
           RETURNS integer LANGUAGE SQL AS 'SELECT state / value'; \
         CREATE FUNCTION aggregate_strict_final_extra(state bigint, value integer) \
           RETURNS bigint LANGUAGE SQL STRICT AS 'SELECT state'; \
         CREATE FUNCTION aggregate_sum_combine(left_state bigint, right_state bigint) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT coalesce(left_state, 0) + coalesce(right_state, 0)'; \
         CREATE FUNCTION aggregate_polymorphic_first(state anyelement, value anyelement) \
           RETURNS anyelement LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_polymorphic_array_first(state anyarray, value anyarray) \
           RETURNS anyarray LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_compatible_first_state(state anycompatible, value anycompatible) \
           RETURNS anycompatible LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_tick_state(state bigint) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT coalesce(state, 0) + 1'; \
         CREATE AGGREGATE aggregate_sum(integer) ( \
           SFUNC = aggregate_sum_state, STYPE = bigint, FINALFUNC = aggregate_double, \
           MSFUNC = aggregate_sum_state, MINVFUNC = aggregate_sum_inverse, MSTYPE = bigint, \
           MFINALFUNC = aggregate_double \
         ); \
         CREATE AGGREGATE aggregate_offset_sum(integer ORDER BY integer) ( \
           SFUNC = aggregate_sum_state, STYPE = bigint, INITCOND = '0', \
           FINALFUNC = aggregate_offset \
         ); \
         CREATE AGGREGATE ordered_concat(ORDER BY integer) ( \
           SFUNC = aggregate_concat_state, STYPE = text, INITCOND = '' \
         ); \
         CREATE AGGREGATE aggregate_product(integer) ( \
           SFUNC = aggregate_strict_product, STYPE = integer, PARALLEL = SAFE \
         ); \
         CREATE AGGREGATE aggregate_old_total( \
           BASETYPE = integer, SFUNC = aggregate_sum_state, STYPE = bigint \
         ); \
         CREATE AGGREGATE aggregate_old_tick( \
           BASETYPE = any, SFUNC = aggregate_tick_state, STYPE = bigint, INITCOND = '0' \
         ); \
         CREATE AGGREGATE aggregate_first(anyelement) ( \
           SFUNC = aggregate_polymorphic_first, STYPE = anyelement \
         ); \
         CREATE AGGREGATE aggregate_array_first(anyarray) ( \
           SFUNC = aggregate_polymorphic_array_first, STYPE = anyarray \
         ); \
         CREATE AGGREGATE aggregate_compatible_first(anycompatible) ( \
           SFUNC = aggregate_compatible_first_state, STYPE = anycompatible \
         ); \
         CREATE AGGREGATE aggregate_window_unsafe(integer) ( \
           SFUNC = aggregate_sum_state, STYPE = bigint, FINALFUNC = aggregate_double, \
           FINALFUNC_MODIFY = READ_WRITE \
         )",
    );
    assert!(
        !String::from_utf8_lossy(&setup).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&setup)
    );
    let state_slot = engine
        .storage
        .routine_slot_for_call_oids(
            "aggregate_sum_state",
            &[crate::sql::types::oid::INT8, crate::sql::types::oid::INT4],
            0,
        )
        .unwrap();
    assert!(
        engine
            .storage
            .routine_for_bound_call(
                state_slot,
                &[crate::sql::types::oid::TEXT, crate::sql::types::oid::TEXT],
                0,
            )
            .is_none()
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT g, aggregate_sum(v) FROM aggregate_input GROUP BY g ORDER BY g; \
             SELECT aggregate_sum(v), aggregate_sum(DISTINCT v) FROM aggregate_input"
        )),
        ["1|12", "2|10", "22|22"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT aggregate_old_total(v) FROM aggregate_input"
        )),
        ["11"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT aggregate_old_tick(*) FROM aggregate_input; \
             SELECT aggregate_first(v), aggregate_first(g::text) FROM aggregate_input; \
             SELECT aggregate_array_first(ARRAY[v])::text, \
                    aggregate_compatible_first(v::bigint) FROM aggregate_input"
        )),
        ["5", "3|1", "{3}|3"]
    );
    assert_eq!(
        row_description_type_oids(&describe_with(
            &mut engine,
            &mut budget,
            "SELECT aggregate_first(1), aggregate_first('x'::text), \
                    aggregate_array_first(ARRAY[1])"
        )),
        [
            crate::sql::types::oid::INT4,
            crate::sql::types::oid::TEXT,
            crate::sql::types::ColType::Array(crate::sql::types::ArrElem::Int4).oid(),
        ]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT g, aggregate_product(v) FROM aggregate_input GROUP BY g ORDER BY g; \
             SELECT aggregate_product(v) FROM aggregate_input WHERE false"
        )),
        ["1|6", "2|5", "NULL"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT aggregate_sum(v) OVER (ORDER BY v ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) \
               FROM aggregate_input ORDER BY v"
        )),
        ["2", "6", "12", "22", "22"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT aggregate_sum(v) OVER (ORDER BY v ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) \
               FROM aggregate_input ORDER BY v"
        )),
        ["2", "6", "10", "16", "10"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT aggregate_offset_sum(10) WITHIN GROUP (ORDER BY v DESC), \
                    ordered_concat() WITHIN GROUP (ORDER BY v DESC) \
               FROM aggregate_input; \
             SELECT aggregate_offset_sum(10) WITHIN GROUP (ORDER BY v) \
               FROM aggregate_input WHERE false"
        )),
        ["21|5321", "10"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT prokind, prorettype FROM pg_proc WHERE proname = 'aggregate_sum'"
        )),
        [format!("a|{}", crate::sql::types::oid::INT8)]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT aggkind, aggnumdirectargs, aggtransfn::oid, aggfinalfn::oid, \
                    aggtranstype, agginitval \
               FROM pg_aggregate a JOIN pg_proc p ON p.oid = a.aggfnoid \
              WHERE p.proname = 'aggregate_sum'"
        )),
        [format!(
            "n|0|{}|{}|{}|NULL",
            engine
                .storage
                .routine_for_call_oids(
                    "aggregate_sum_state",
                    &[crate::sql::types::oid::INT8, crate::sql::types::oid::INT4],
                    0
                )
                .map(|routine| crate::storage::routine_oid(&routine))
                .unwrap(),
            engine
                .storage
                .routine_for_call_oids("aggregate_double", &[crate::sql::types::oid::INT8], 0)
                .map(|routine| crate::storage::routine_oid(&routine))
                .unwrap(),
            crate::sql::types::oid::INT8,
        )]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT proisstrict, provolatile, proparallel FROM pg_proc \
              WHERE proname = 'aggregate_strict_product'"
        )),
        ["t|i|s"]
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT p.proname, p.prorettype::regtype::text, \
                    a.aggtranstype::regtype::text \
               FROM pg_proc p JOIN pg_aggregate a ON a.aggfnoid = p.oid \
              WHERE p.proname IN ('aggregate_first', 'aggregate_array_first', \
                                  'aggregate_compatible_first') ORDER BY p.proname"
        )),
        [
            "aggregate_array_first|anyarray|anyarray",
            "aggregate_compatible_first|anycompatible|anycompatible",
            "aggregate_first|anyelement|anyelement",
        ]
    );
    let undetermined_function = run_with(
        &mut engine,
        &mut budget,
        "CREATE FUNCTION aggregate_invalid_polymorphic_result() RETURNS anyelement \
           LANGUAGE SQL AS 'SELECT NULL'",
    );
    assert!(String::from_utf8_lossy(&undetermined_function).contains("42P13"));
    let missing_old_base_type = run_with(
        &mut engine,
        &mut budget,
        "CREATE AGGREGATE aggregate_missing_base_type( \
           SFUNC = aggregate_tick_state, STYPE = bigint, INITCOND = '0' \
         )",
    );
    assert!(String::from_utf8_lossy(&missing_old_base_type).contains("42P13"));
    let polymorphic_state = run_with(
        &mut engine,
        &mut budget,
        "CREATE FUNCTION aggregate_polymorphic_concrete_state(state anyelement, value integer) \
           RETURNS anyelement LANGUAGE SQL AS 'SELECT state'; \
         CREATE AGGREGATE aggregate_invalid_polymorphic_state(integer) ( \
           SFUNC = aggregate_polymorphic_concrete_state, STYPE = anyelement \
         )",
    );
    assert!(String::from_utf8_lossy(&polymorphic_state).contains("42P13"));
    let invalid_strict = run_with(
        &mut engine,
        &mut budget,
        "CREATE AGGREGATE invalid_strict_sum(integer) ( \
           SFUNC = aggregate_strict_mismatch, STYPE = bigint \
         )",
    );
    assert!(String::from_utf8_lossy(&invalid_strict).contains("42P13"));
    let invalid_serde = run_with(
        &mut engine,
        &mut budget,
        "CREATE AGGREGATE invalid_serialized_sum(integer) ( \
           SFUNC = aggregate_sum_state, STYPE = bigint, \
           COMBINEFUNC = aggregate_sum_combine, \
           SERIALFUNC = missing_serialize, DESERIALFUNC = missing_deserialize \
         )",
    );
    assert!(String::from_utf8_lossy(&invalid_serde).contains("42P13"));
    let invalid_moving_strictness = run_with(
        &mut engine,
        &mut budget,
        "CREATE AGGREGATE aggregate_invalid_moving_strictness(integer) ( \
           SFUNC = aggregate_strict_product, STYPE = integer, \
           MSFUNC = aggregate_strict_product, \
           MINVFUNC = aggregate_nonstrict_product_inverse, MSTYPE = integer \
         )",
    );
    assert!(String::from_utf8_lossy(&invalid_moving_strictness).contains("42P13"));
    let invalid_final_extra = run_with(
        &mut engine,
        &mut budget,
        "CREATE AGGREGATE aggregate_invalid_final_extra(integer) ( \
           SFUNC = aggregate_sum_state, STYPE = bigint, \
           FINALFUNC = aggregate_strict_final_extra, FINALFUNC_EXTRA \
         )",
    );
    assert!(String::from_utf8_lossy(&invalid_final_extra).contains("42P13"));
    let unsafe_window = run_with(
        &mut engine,
        &mut budget,
        "SELECT aggregate_window_unsafe(v) OVER () FROM aggregate_input",
    );
    assert!(String::from_utf8_lossy(&unsafe_window).contains("0A000"));
    let changed_result = run_with(
        &mut engine,
        &mut budget,
        "CREATE OR REPLACE AGGREGATE aggregate_sum(integer) ( \
           SFUNC = aggregate_concat_state, STYPE = text, INITCOND = '' \
         )",
    );
    assert!(String::from_utf8_lossy(&changed_result).contains("42P13"));
    let changed_kind = run_with(
        &mut engine,
        &mut budget,
        "CREATE OR REPLACE AGGREGATE aggregate_sum(ORDER BY integer) ( \
           SFUNC = aggregate_sum_state, STYPE = bigint \
         )",
    );
    assert!(String::from_utf8_lossy(&changed_kind).contains("42P13"));
    let altered = run_with(
        &mut engine,
        &mut budget,
        "ALTER AGGREGATE aggregate_sum(integer) RENAME TO aggregate_total; \
         SELECT aggregate_total(v) FROM aggregate_input; \
         DROP AGGREGATE aggregate_total(integer)",
    );
    assert_eq!(
        data_rows(&altered),
        ["22"],
        "{}",
        String::from_utf8_lossy(&altered)
    );
}

#[test]
fn user_defined_aggregate_survives_wal_and_checkpoint_recovery() {
    let mut config = test_config("user_aggregate_recovery");
    config.max_tables = 16;
    config.object_store_on = true;
    config.object_store_sim = true;
    config.object_store_namespace = format!("user-aggregate-recovery-{}", std::process::id());
    config.wal_upload = true;
    config.wal_upload_sync = true;
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    {
        let mut budget = Budget::new(1 << 29);
        let mut engine = Engine::new(&config, &mut budget).unwrap();
        let created = run_with(
            &mut engine,
            &mut budget,
            "CREATE TABLE aggregate_recovery_input (value integer); \
             INSERT INTO aggregate_recovery_input VALUES (2), (4), (8); \
             CREATE FUNCTION aggregate_recovery_state(state bigint, value integer) \
               RETURNS bigint LANGUAGE SQL AS 'SELECT coalesce(state, 1) * value'; \
             CREATE FUNCTION aggregate_recovery_concat(state text, value integer) \
               RETURNS text LANGUAGE SQL AS 'SELECT concat(state, value)'; \
             CREATE FUNCTION aggregate_recovery_combine(left_state text, right_state text) \
               RETURNS text LANGUAGE SQL AS 'SELECT concat(left_state, right_state)'; \
             CREATE FUNCTION aggregate_recovery_first(state anyelement, value anyelement) \
               RETURNS anyelement LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
             CREATE AGGREGATE aggregate_product(integer) ( \
               SFUNC = aggregate_recovery_state, STYPE = bigint \
             ); \
             CREATE AGGREGATE aggregate_serial_concat(integer) ( \
               SFUNC = aggregate_recovery_concat, STYPE = text, INITCOND = '', \
               COMBINEFUNC = aggregate_recovery_combine \
             ); \
             CREATE AGGREGATE aggregate_recovery_first(anyelement) ( \
               SFUNC = aggregate_recovery_first, STYPE = anyelement \
             )",
        );
        assert!(
            !String::from_utf8_lossy(&created).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&created)
        );
        let aggregate_slot = engine
            .storage
            .routine_slot_by_signature("public", "aggregate_product", &[ColType::Int4], 0)
            .unwrap();
        let crate::storage::RoutineKind::Aggregate(aggregate) =
            engine.storage.routine(aggregate_slot).kind
        else {
            panic!("created routine is not an aggregate")
        };
        let encoded = aggregate.encode_wire();
        assert_eq!(
            crate::storage::AggregateRoutine::decode_wire(encoded.as_str()),
            Some(aggregate),
            "{}",
            encoded.as_str()
        );
        engine.commit_wal().unwrap();
    }
    {
        let mut budget = Budget::new(1 << 29);
        let mut recovered = Engine::new(&config, &mut budget).unwrap();
        let aggregate_slot = recovered
            .storage
            .routine_slot_by_signature("public", "aggregate_product", &[ColType::Int4], 0)
            .expect("aggregate recovered from WAL");
        assert!(matches!(
            recovered.storage.routine(aggregate_slot).kind,
            crate::storage::RoutineKind::Aggregate(_)
        ));
        let result = run_with(
            &mut recovered,
            &mut budget,
            "SELECT aggregate_product(value), aggregate_serial_concat(value), \
                    aggregate_recovery_first(value) \
               FROM aggregate_recovery_input",
        );
        assert_eq!(
            data_rows(&result),
            ["64|248|2"],
            "{}",
            String::from_utf8_lossy(&result)
        );
        let replaced = run_with(
            &mut recovered,
            &mut budget,
            "CREATE OR REPLACE AGGREGATE aggregate_product(integer) ( \
               SFUNC = aggregate_recovery_state, STYPE = bigint, INITCOND = '2' \
             ); \
             SELECT aggregate_product(value) FROM aggregate_recovery_input",
        );
        assert_eq!(data_rows(&replaced), ["128"]);
        assert!(recovered.checkpoint().unwrap());
    }
    {
        let mut budget = Budget::new(1 << 29);
        let mut recovered = Engine::new(&config, &mut budget).unwrap();
        assert_eq!(
            data_rows(&run_with(
                &mut recovered,
                &mut budget,
                "SELECT aggregate_product(value), aggregate_serial_concat(value), \
                        aggregate_recovery_first(value), \
                        aggkind, aggtranstype \
                   FROM aggregate_recovery_input, pg_aggregate a \
                   JOIN pg_proc p ON p.oid = a.aggfnoid \
                  WHERE p.proname = 'aggregate_product' \
                  GROUP BY aggkind, aggtranstype"
            )),
            [format!("128|248|2|n|{}", crate::sql::types::oid::INT8)]
        );
    }
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    std::fs::remove_dir_all(&config.data_dir).unwrap();
}

#[test]
fn user_defined_aggregate_resolves_every_postgresql_polymorphic_family() {
    let mut config = test_config("user-defined-aggregate-polymorphic-families");
    config.max_tables = 32;
    let mut budget = Budget::new(1 << 28);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let created = run_with(
        &mut engine,
        &mut budget,
        "CREATE TYPE aggregate_polymorphic_mood AS ENUM ('low', 'high'); \
         CREATE FUNCTION aggregate_anynonarray_state(state anynonarray, value anynonarray) \
           RETURNS anynonarray LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_anyenum_state(state anyenum, value anyenum) \
           RETURNS anyenum LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_anyrange_state(state anyrange, value anyrange) \
           RETURNS anyrange LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_anymultirange_state(state anymultirange, value anymultirange) \
           RETURNS anymultirange LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_anycompatiblearray_state( \
           state anycompatiblearray, value anycompatiblearray) \
           RETURNS anycompatiblearray LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_anycompatiblenonarray_state( \
           state anycompatiblenonarray, value anycompatiblenonarray) \
           RETURNS anycompatiblenonarray LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_anycompatiblerange_state( \
           state anycompatiblerange, value anycompatiblerange) \
           RETURNS anycompatiblerange LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_anycompatiblemultirange_state( \
           state anycompatiblemultirange, value anycompatiblemultirange) \
           RETURNS anycompatiblemultirange LANGUAGE SQL AS 'SELECT coalesce(state, value)'; \
         CREATE FUNCTION aggregate_compatible_pair_state( \
           state anycompatible, left_value anycompatible, right_value anycompatible) \
           RETURNS anycompatible LANGUAGE SQL \
           AS 'SELECT coalesce(state, left_value, right_value)'; \
         CREATE AGGREGATE aggregate_anynonarray(anynonarray) ( \
           SFUNC = aggregate_anynonarray_state, STYPE = anynonarray); \
         CREATE AGGREGATE aggregate_anyenum(anyenum) ( \
           SFUNC = aggregate_anyenum_state, STYPE = anyenum); \
         CREATE AGGREGATE aggregate_anyrange(anyrange) ( \
           SFUNC = aggregate_anyrange_state, STYPE = anyrange); \
         CREATE AGGREGATE aggregate_anymultirange(anymultirange) ( \
           SFUNC = aggregate_anymultirange_state, STYPE = anymultirange); \
         CREATE AGGREGATE aggregate_anycompatiblearray(anycompatiblearray) ( \
           SFUNC = aggregate_anycompatiblearray_state, STYPE = anycompatiblearray); \
         CREATE AGGREGATE aggregate_anycompatiblenonarray(anycompatiblenonarray) ( \
           SFUNC = aggregate_anycompatiblenonarray_state, STYPE = anycompatiblenonarray); \
         CREATE AGGREGATE aggregate_anycompatiblerange(anycompatiblerange) ( \
           SFUNC = aggregate_anycompatiblerange_state, STYPE = anycompatiblerange); \
         CREATE AGGREGATE aggregate_anycompatiblemultirange(anycompatiblemultirange) ( \
           SFUNC = aggregate_anycompatiblemultirange_state, \
           STYPE = anycompatiblemultirange); \
         CREATE AGGREGATE aggregate_compatible_pair(anycompatible, anycompatible) ( \
           SFUNC = aggregate_compatible_pair_state, STYPE = anycompatible)",
    );
    assert!(
        !String::from_utf8_lossy(&created).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&created)
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT aggregate_anynonarray(value) \
               FROM (VALUES (2::bigint), (3::bigint)) input(value); \
             SELECT aggregate_anyenum(value)::text \
               FROM (VALUES ('low'::aggregate_polymorphic_mood), \
                            ('high'::aggregate_polymorphic_mood)) input(value); \
             SELECT aggregate_anyrange(value)::text \
               FROM (VALUES ('[1,3)'::int4range), ('[5,7)'::int4range)) input(value); \
             SELECT aggregate_anymultirange(value)::text \
               FROM (VALUES ('{[1,3)}'::int4multirange), \
                            ('{[5,7)}'::int4multirange)) input(value); \
             SELECT aggregate_anycompatiblearray(value)::text \
               FROM (VALUES (ARRAY[1,2]), (ARRAY[3,4])) input(value); \
             SELECT aggregate_anycompatiblenonarray(value) \
               FROM (VALUES (2::bigint), (3::bigint)) input(value); \
             SELECT aggregate_anycompatiblerange(value)::text \
               FROM (VALUES ('[1,3)'::int4range), ('[5,7)'::int4range)) input(value); \
             SELECT aggregate_anycompatiblemultirange(value)::text \
               FROM (VALUES ('{[1,3)}'::int4multirange), \
                            ('{[5,7)}'::int4multirange)) input(value); \
             SELECT aggregate_compatible_pair(left_value, right_value), \
                    pg_typeof(aggregate_compatible_pair(left_value, right_value)) \
               FROM (VALUES (2::integer, 3::bigint), \
                            (4::integer, 5::bigint)) input(left_value, right_value)"
        )),
        [
            "2", "low", "[1,3)", "{[1,3)}", "{1,2}", "2", "[1,3)", "{[1,3)}", "2|bigint",
        ]
    );
}

#[test]
fn user_defined_aggregate_combines_bounded_spill_partitions() {
    let mut config = test_config("user-defined-aggregate-partial-spill");
    config.max_tables = 16;
    config.object_store_on = true;
    config.object_store_sim = true;
    config.object_store_namespace = format!("user-aggregate-spill-{}", std::process::id());
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    let mut budget = Budget::new(1 << 29);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let output = run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE aggregate_spill_input (group_id integer, value integer); \
         INSERT INTO aggregate_spill_input \
           SELECT value % 3, 1 FROM generate_series(1, 600) AS series(value); \
         CREATE FUNCTION aggregate_spill_state(state bigint, value integer) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT coalesce(state, 0) + value'; \
         CREATE FUNCTION aggregate_spill_combine(left_state bigint, right_state bigint) \
           RETURNS bigint LANGUAGE SQL \
           AS 'SELECT coalesce(left_state, 0) + coalesce(right_state, 0)'; \
         CREATE AGGREGATE aggregate_spill_total(integer) ( \
           SFUNC = aggregate_spill_state, STYPE = bigint, INITCOND = '0', \
           COMBINEFUNC = aggregate_spill_combine, PARALLEL = SAFE); \
         SELECT group_id, aggregate_spill_total(value) \
           FROM aggregate_spill_input GROUP BY group_id ORDER BY group_id; \
         SELECT aggregate_spill_total(value) FROM aggregate_spill_input",
    );
    assert_eq!(
        data_rows(&output),
        ["0|200", "1|200", "2|200", "600"],
        "{}",
        String::from_utf8_lossy(&output)
    );
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    std::fs::remove_dir_all(&config.data_dir).unwrap();
}

#[test]
fn user_defined_aggregate_ownership_privileges_and_dependencies_are_typed() {
    let mut config = test_config("user-defined-aggregate-dependencies");
    config.max_tables = 32;
    let mut budget = Budget::new(1 << 28);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let setup = run_with(
        &mut engine,
        &mut budget,
        "CREATE ROLE aggregate_owner; \
         CREATE ROLE aggregate_reader; \
         GRANT CREATE ON SCHEMA public TO aggregate_owner; \
         CREATE SCHEMA aggregate_target; \
         CREATE FUNCTION protected_aggregate_state(state bigint, value integer) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT coalesce(state, 0) + value'; \
         REVOKE EXECUTE ON FUNCTION protected_aggregate_state(bigint, integer) FROM PUBLIC",
    );
    assert!(!String::from_utf8_lossy(&setup).contains("ERROR"));
    let denied = run_with(
        &mut engine,
        &mut budget,
        "SET ROLE aggregate_owner; \
         CREATE AGGREGATE protected_total(integer) ( \
           SFUNC = protected_aggregate_state, STYPE = bigint, INITCOND = '0' \
         )",
    );
    assert!(String::from_utf8_lossy(&denied).contains("42501"));
    let lifecycle = run_with(
        &mut engine,
        &mut budget,
        "RESET ROLE; \
         GRANT EXECUTE ON FUNCTION protected_aggregate_state(bigint, integer) TO aggregate_owner; \
         SET ROLE aggregate_owner; \
         CREATE AGGREGATE protected_total(integer) ( \
           SFUNC = protected_aggregate_state, STYPE = bigint, INITCOND = '0' \
         ); \
         RESET ROLE; \
         ALTER AGGREGATE protected_total(integer) OWNER TO postgres; \
         ALTER AGGREGATE protected_total(integer) SET SCHEMA aggregate_target; \
         ALTER AGGREGATE aggregate_target.protected_total(integer) RENAME TO moved_total; \
         SELECT aggregate_target.moved_total(value) FROM (VALUES (2), (3)) input(value); \
         SELECT namespace.nspname, pg_get_userbyid(proc.proowner), \
                proc.oid::regprocedure::text, pg_get_function_result(proc.oid) \
           FROM pg_proc proc JOIN pg_namespace namespace ON namespace.oid = proc.pronamespace \
          WHERE proc.proname = 'moved_total'",
    );
    assert_eq!(
        data_rows(&lifecycle),
        ["5", "aggregate_target|postgres|moved_total(integer)|bigint"],
        "{}",
        String::from_utf8_lossy(&lifecycle)
    );
    let replaced = run_with(
        &mut engine,
        &mut budget,
        "CREATE OR REPLACE AGGREGATE aggregate_target.moved_total(integer) ( \
           SFUNC = protected_aggregate_state, STYPE = bigint, INITCOND = '10' \
         ); \
         SELECT aggregate_target.moved_total(value) FROM (VALUES (2), (3)) input(value)",
    );
    assert_eq!(
        data_rows(&replaced),
        ["15"],
        "{}",
        String::from_utf8_lossy(&replaced)
    );
    let denied_call = run_with(
        &mut engine,
        &mut budget,
        "REVOKE EXECUTE ON ROUTINE aggregate_target.moved_total(integer) FROM PUBLIC; \
         SET ROLE aggregate_reader; \
         SELECT aggregate_target.moved_total(value) FROM (VALUES (2), (3)) input(value)",
    );
    assert!(
        String::from_utf8_lossy(&denied_call).contains("42501"),
        "{}",
        String::from_utf8_lossy(&denied_call)
    );
    let granted_call = run_with(
        &mut engine,
        &mut budget,
        "RESET ROLE; \
         GRANT EXECUTE ON ROUTINE aggregate_target.moved_total(integer) TO aggregate_reader; \
         SET ROLE aggregate_reader; \
         SELECT aggregate_target.moved_total(value) FROM (VALUES (2), (3)) input(value); \
         RESET ROLE",
    );
    assert_eq!(
        data_rows(&granted_call),
        ["15"],
        "{}",
        String::from_utf8_lossy(&granted_call)
    );
    let restricted = run_with(
        &mut engine,
        &mut budget,
        "DROP FUNCTION protected_aggregate_state(bigint, integer)",
    );
    assert!(String::from_utf8_lossy(&restricted).contains("2BP01"));
    let cascade = run_with(
        &mut engine,
        &mut budget,
        "DROP FUNCTION protected_aggregate_state(bigint, integer) CASCADE; \
         SELECT count(*) FROM pg_proc WHERE proname = 'moved_total'",
    );
    assert_eq!(data_rows(&cascade), ["0"]);
}

#[test]
fn user_defined_aggregate_type_dependencies_restrict_and_cascade_without_dangling_routines() {
    let mut config = test_config("user-defined-aggregate-type-dependencies");
    config.max_tables = 32;
    let mut budget = Budget::new(1 << 28);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let setup = run_with(
        &mut engine,
        &mut budget,
        "CREATE DOMAIN aggregate_domain AS integer; \
         CREATE DOMAIN aggregate_state_domain AS bigint; \
         CREATE FUNCTION aggregate_domain_state(state bigint, value aggregate_domain) \
           RETURNS bigint LANGUAGE SQL AS 'SELECT coalesce(state, 0) + value'; \
         CREATE AGGREGATE aggregate_domain_total(aggregate_domain) ( \
           SFUNC = aggregate_domain_state, STYPE = bigint, INITCOND = '0' \
         ); \
         CREATE FUNCTION aggregate_typed_state(state aggregate_state_domain, value integer) \
           RETURNS aggregate_state_domain LANGUAGE SQL \
           AS 'SELECT (coalesce(state, 0) + value)::aggregate_state_domain'; \
         CREATE AGGREGATE aggregate_typed_total(integer) ( \
           SFUNC = aggregate_typed_state, STYPE = aggregate_state_domain, INITCOND = '0' \
         ); \
         CREATE TYPE aggregate_payload AS (value integer); \
         CREATE FUNCTION aggregate_payload_marker(value aggregate_payload) \
           RETURNS integer LANGUAGE SQL AS 'SELECT 1'",
    );
    assert!(
        !String::from_utf8_lossy(&setup).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&setup)
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT aggregate_typed_total(value), p.prorettype = t.oid \
               FROM (VALUES (2), (3)) input(value), pg_proc p, pg_type t \
              WHERE p.proname = 'aggregate_typed_total' \
                AND t.typname = 'aggregate_state_domain' \
              GROUP BY p.prorettype, t.oid"
        )),
        ["5|t"]
    );
    let domain_restrict = run_with(&mut engine, &mut budget, "DROP DOMAIN aggregate_domain");
    assert!(String::from_utf8_lossy(&domain_restrict).contains("2BP01"));
    let composite_restrict = run_with(&mut engine, &mut budget, "DROP TYPE aggregate_payload");
    assert!(String::from_utf8_lossy(&composite_restrict).contains("2BP01"));
    let state_restrict = run_with(
        &mut engine,
        &mut budget,
        "DROP DOMAIN aggregate_state_domain",
    );
    assert!(String::from_utf8_lossy(&state_restrict).contains("2BP01"));
    let dropped = run_with(
        &mut engine,
        &mut budget,
        "DROP DOMAIN aggregate_domain CASCADE; \
         DROP TYPE aggregate_payload CASCADE; \
         DROP DOMAIN aggregate_state_domain CASCADE; \
         SELECT count(*) FROM pg_proc \
          WHERE proname IN ('aggregate_domain_state', 'aggregate_domain_total', \
                            'aggregate_typed_state', 'aggregate_typed_total', \
                            'aggregate_payload_marker')",
    );
    assert_eq!(
        data_rows(&dropped),
        ["0"],
        "{}",
        String::from_utf8_lossy(&dropped)
    );
}

