#[test]
fn routine_identity_changes_are_typed_transactional_and_durable() {
    let mut config = test_config("routine-identity");
    config.object_store_on = true;
    config.object_store_sim = true;
    config.object_store_namespace = format!("routine-identity-{}", std::process::id());
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    let mut budget = Budget::new(1 << 29);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE SCHEMA routine_target;
         CREATE FUNCTION routine_lifecycle(integer) RETURNS integer LANGUAGE SQL AS 'SELECT 1';
         CREATE PROCEDURE routine_lifecycle(text) LANGUAGE SQL AS 'SELECT 1'",
    );
    let output = run_with(
        &mut engine,
        &mut budget,
        "BEGIN;
         ALTER ROUTINE routine_lifecycle(integer) RENAME TO routine_renamed;
         ALTER PROCEDURE routine_lifecycle(text) SET SCHEMA routine_target;
         SELECT proname, nspname FROM pg_proc JOIN pg_namespace ON pronamespace = pg_namespace.oid
          WHERE proname IN ('routine_lifecycle', 'routine_renamed') ORDER BY proname, nspname;
         ROLLBACK;
         SELECT proname, nspname FROM pg_proc JOIN pg_namespace ON pronamespace = pg_namespace.oid
          WHERE proname = 'routine_lifecycle' ORDER BY nspname;
         ALTER FUNCTION routine_lifecycle(integer) RENAME TO routine_renamed;
         ALTER PROCEDURE routine_lifecycle(text) SET SCHEMA routine_target;
         SELECT routine_renamed(1);",
    );
    assert_eq!(
        data_rows(&output),
        [
            "routine_lifecycle|routine_target",
            "routine_renamed|public",
            "routine_lifecycle|public",
            "routine_lifecycle|public",
            "1",
        ],
        "{}",
        String::from_utf8_lossy(&output)
    );
    assert!(String::from_utf8_lossy(&output).contains("ALTER ROUTINE"));
    drop(engine);

    let mut restarted_budget = Budget::new(1 << 29);
    let mut restarted = Engine::new(&config, &mut restarted_budget).unwrap();
    let output = run_with(
        &mut restarted,
        &mut restarted_budget,
        "SELECT proname, nspname FROM pg_proc JOIN pg_namespace ON pronamespace = pg_namespace.oid
         WHERE proname IN ('routine_lifecycle', 'routine_renamed') ORDER BY proname, nspname",
    );
    assert_eq!(
        data_rows(&output),
        ["routine_lifecycle|routine_target", "routine_renamed|public"],
        "{}",
        String::from_utf8_lossy(&output)
    );
    assert!(restarted.checkpoint().unwrap());
    drop(restarted);

    let mut checkpoint_budget = Budget::new(1 << 29);
    let mut checkpoint_restarted = Engine::new(&config, &mut checkpoint_budget).unwrap();
    let output = run_with(
        &mut checkpoint_restarted,
        &mut checkpoint_budget,
        "SELECT proname, nspname FROM pg_proc JOIN pg_namespace ON pronamespace = pg_namespace.oid
         WHERE proname IN ('routine_lifecycle', 'routine_renamed') ORDER BY proname, nspname;
         DROP ROUTINE routine_target.routine_lifecycle(text), routine_renamed(integer);
         SELECT count(*) FROM pg_proc WHERE proname IN ('routine_lifecycle', 'routine_renamed');",
    );
    assert_eq!(
        data_rows(&output),
        [
            "routine_lifecycle|routine_target",
            "routine_renamed|public",
            "0",
        ],
        "{}",
        String::from_utf8_lossy(&output)
    );
    std::fs::remove_dir_all(&config.data_dir).unwrap();
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
}

#[test]
fn sql_write_function_survives_wal_recovery() {
    let config = test_config("sql_write_function_recovery");
    {
        let mut budget = Budget::new(1 << 28);
        let mut engine = Engine::new(&config, &mut budget).unwrap();
        let setup = run_with(
            &mut engine,
            &mut budget,
            "CREATE TABLE write_function_log (id integer PRIMARY KEY, value integer); \
             CREATE FUNCTION write_function_value(value integer) RETURNS integer LANGUAGE SQL \
               AS 'INSERT INTO write_function_log VALUES ($1, $1 + 1) RETURNING value + 1'; \
             CREATE FUNCTION write_function_rows(value integer) RETURNS SETOF integer LANGUAGE SQL \
               AS 'INSERT INTO write_function_log VALUES ($1, $1 + 1) RETURNING value'; \
             CREATE FUNCTION recovered_set_void() RETURNS SETOF void LANGUAGE SQL \
               AS 'SELECT NULL UNION ALL SELECT NULL'; \
             CREATE FUNCTION resolved_routine_arg(value integer) RETURNS integer LANGUAGE SQL \
               AS 'SELECT resolved_routine_arg.value + value FROM (VALUES (2)) AS source(value)'; \
             CREATE FUNCTION shadowed_routine_arg(value integer) RETURNS integer LANGUAGE SQL \
               AS 'SELECT shadowed_routine_arg.value + value FROM (VALUES (2)) AS shadowed_routine_arg(value)'; \
             SELECT write_function_value(40); \
             SELECT resolved_routine_arg(40); \
             SELECT shadowed_routine_arg(40)",
        );
        assert_eq!(
            data_rows(&setup),
            ["42", "42", "4"],
            "{}",
            String::from_utf8_lossy(&setup)
        );
        engine.commit_wal().unwrap();
    }
    let mut recovered_budget = Budget::new(1 << 28);
    let mut recovered = Engine::new(&config, &mut recovered_budget).unwrap();
    let output = run_with(
        &mut recovered,
        &mut recovered_budget,
        "SELECT write_function_value(41); \
         SELECT resolved_routine_arg(41); \
         SELECT value FROM write_function_rows(42) AS result(value); \
         SELECT id, value FROM write_function_log ORDER BY id; \
         SELECT count(*) FROM recovered_set_void() AS result(value)",
    );
    assert_eq!(
        data_rows(&output),
        ["43", "43", "43", "40|41", "41|42", "42|43", "0"],
        "{}",
        String::from_utf8_lossy(&output)
    );
    std::fs::remove_dir_all(&config.data_dir).unwrap();
}

#[test]
fn sql_procedure_call_is_typed_durable_and_catalogued() {
    let config = test_config("sql_procedure_call");
    {
        let mut budget = Budget::new(1 << 28);
        let mut engine = Engine::new(&config, &mut budget).unwrap();
        run_with(
            &mut engine,
            &mut budget,
            "CREATE TABLE procedure_log (value integer)",
        );
        let created = run_with(
            &mut engine,
            &mut budget,
            "CREATE PROCEDURE log_value(value integer) LANGUAGE SQL AS 'INSERT INTO procedure_log VALUES ($1)'",
        );
        assert!(
            !String::from_utf8_lossy(&created).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&created)
        );
        let acl_setup = run_with(
            &mut engine,
            &mut budget,
            "CREATE ROLE procedure_reader;
             GRANT INSERT ON TABLE procedure_log TO procedure_reader;",
        );
        assert!(
            !String::from_utf8_lossy(&acl_setup).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&acl_setup)
        );
        run_with(
            &mut engine,
            &mut budget,
            "REVOKE EXECUTE ON PROCEDURE log_value(integer) FROM PUBLIC",
        );
        let acl_denied = run_with(
            &mut engine,
            &mut budget,
            "SET ROLE procedure_reader; CALL log_value(40)",
        );
        assert!(
            String::from_utf8_lossy(&acl_denied).contains("42501"),
            "{}",
            String::from_utf8_lossy(&acl_denied)
        );
        run_with(&mut engine, &mut budget, "RESET ROLE");
        let acl_grant = run_with(
            &mut engine,
            &mut budget,
            "GRANT EXECUTE ON PROCEDURE log_value(integer) TO procedure_reader;
             SET ROLE procedure_reader;
             CALL log_value(40);
             RESET ROLE;",
        );
        assert!(
            !String::from_utf8_lossy(&acl_grant).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&acl_grant)
        );
        let called = run_with(&mut engine, &mut budget, "CALL log_value(41)");
        assert!(
            !String::from_utf8_lossy(&called).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&called)
        );
        let multi_created = run_with(
            &mut engine,
            &mut budget,
            "CREATE PROCEDURE log_pair(value integer) LANGUAGE SQL AS \
             'WITH routine_input AS (SELECT $1 AS value), \
                   incremented_input AS (SELECT value + 1 AS value FROM routine_input) \
              INSERT INTO procedure_log SELECT value FROM routine_input UNION ALL SELECT value FROM incremented_input; \
              SELECT value FROM procedure_log WHERE value = $1'",
        );
        assert!(
            !String::from_utf8_lossy(&multi_created).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&multi_created)
        );
        let multi_called = run_with(&mut engine, &mut budget, "CALL log_pair(42)");
        assert!(
            data_rows(&multi_called).is_empty()
                && String::from_utf8_lossy(&multi_called).contains("CALL"),
            "procedure results stay internal: {}",
            String::from_utf8_lossy(&multi_called)
        );
        let failing_created = run_with(
            &mut engine,
            &mut budget,
            "CREATE PROCEDURE log_then_fail(value integer) LANGUAGE SQL AS \
             'INSERT INTO procedure_log VALUES ($1); INSERT INTO missing_log VALUES ($1)'",
        );
        assert!(
            !String::from_utf8_lossy(&failing_created).contains("ERROR"),
            "{}",
            String::from_utf8_lossy(&failing_created)
        );
        let failed = run_with(&mut engine, &mut budget, "CALL log_then_fail(99)");
        assert!(
            String::from_utf8_lossy(&failed).contains("42P01"),
            "{failed:?}"
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT value FROM procedure_log ORDER BY value"
            )),
            ["40", "41", "42", "43"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT prokind, prorettype FROM pg_proc WHERE proname = 'log_value'"
            )),
            ["p|2278"]
        );
        assert_eq!(
            data_rows(&run_with(
                &mut engine,
                &mut budget,
                "SELECT routine_type, data_type FROM information_schema.routines WHERE routine_name = 'log_value'"
            )),
            ["PROCEDURE|NULL"]
        );
        engine.commit_wal().unwrap();
    }
    let mut budget = Budget::new(1 << 28);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    run_with(&mut engine, &mut budget, "CALL log_value(42)");
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT value FROM procedure_log ORDER BY value"
        )),
        ["40", "41", "42", "42", "43"]
    );
    let wrong_drop = run_with(&mut engine, &mut budget, "DROP FUNCTION log_value(integer)");
    assert!(String::from_utf8_lossy(&wrong_drop).contains("42883"));
    let dropped = run_with(
        &mut engine,
        &mut budget,
        "DROP PROCEDURE log_value(integer)",
    );
    assert!(
        !String::from_utf8_lossy(&dropped).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&dropped)
    );
    run_with(&mut engine, &mut budget, "DROP PROCEDURE log_pair(integer)");
    run_with(
        &mut engine,
        &mut budget,
        "DROP PROCEDURE log_then_fail(integer)",
    );
}

#[test]
fn routines_retain_catalog_defined_signature_and_result_types() {
    let (mut engine, mut budget) = test_engine();
    let created = run_with(
        &mut engine,
        &mut budget,
        "CREATE TYPE routine_state AS ENUM ('ready', 'done'); \
         CREATE DOMAIN routine_count AS integer CHECK (VALUE > 0); \
         CREATE TYPE routine_pair AS (value integer, label text); \
         CREATE FUNCTION echo_state(value routine_state) RETURNS routine_state LANGUAGE SQL AS 'SELECT $1'; \
         CREATE FUNCTION echo_count(value routine_count) RETURNS routine_count LANGUAGE SQL AS 'SELECT $1'; \
         CREATE FUNCTION echo_counts(vals routine_count[]) RETURNS routine_count[] LANGUAGE SQL AS 'SELECT $1'; \
         CREATE FUNCTION echo_counts_unnamed(routine_count[]) RETURNS routine_count[] LANGUAGE SQL AS 'SELECT $1'; \
         CREATE FUNCTION echo_pair(value routine_pair) RETURNS routine_pair LANGUAGE SQL AS 'SELECT $1'; \
         CREATE FUNCTION routine_overload(value integer) RETURNS text LANGUAGE SQL AS 'SELECT ''integer'''; \
         CREATE FUNCTION routine_overload(value routine_count) RETURNS text LANGUAGE SQL AS 'SELECT ''domain'''; \
         CREATE PROCEDURE accept_state(value routine_state) LANGUAGE SQL AS 'SELECT $1'; \
         CREATE TABLE routine_values (state routine_state, count routine_count, pair routine_pair); \
         INSERT INTO routine_values VALUES ('ready', 5, ROW(9, 'nine')::routine_pair)",
    );
    assert!(
        !String::from_utf8_lossy(&created).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&created)
    );
    let invoked = run_with(
        &mut engine,
        &mut budget,
        "SELECT echo_state('ready'::routine_state)::text, \
                echo_count(3::routine_count)::text, \
                echo_counts(ARRAY[1::routine_count, 2::routine_count]::routine_count[])::text, \
                echo_counts_unnamed(ARRAY[4::routine_count]::routine_count[])::text, \
                echo_pair(ROW(7, 'seven')::routine_pair)::text, \
                routine_overload(1), routine_overload(1::routine_count); \
         SELECT pg_typeof(echo_state('done'::routine_state)), \
                pg_typeof(echo_count(1::routine_count)), \
                pg_typeof(echo_counts(ARRAY[1::routine_count]::routine_count[])), \
                pg_typeof(echo_pair(ROW(1, 'one')::routine_pair)); \
         SELECT echo_state(state), echo_count(count), echo_pair(pair) FROM routine_values; \
         SELECT ROW(echo_state(state), echo_count(count), echo_pair(pair)) FROM routine_values",
    );
    assert!(
        !String::from_utf8_lossy(&invoked).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&invoked)
    );
    assert_eq!(
        data_rows(&invoked),
        [
            "ready|3|{1,2}|{4}|(7,seven)|integer|domain",
            "routine_state|routine_count|routine_count[]|routine_pair",
            "ready|5|(9,nine)",
            "(ready,5,\"(9,nine)\")",
        ]
    );
    let called = run_with(
        &mut engine,
        &mut budget,
        "CALL accept_state('ready'::routine_state)",
    );
    assert!(
        !String::from_utf8_lossy(&called).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&called)
    );
    let catalog = run_with(
        &mut engine,
        &mut budget,
        "SELECT pg_get_function_arguments('echo_state(routine_state)'::regprocedure), \
                pg_get_function_result('echo_state(routine_state)'::regprocedure), \
                pg_get_function_arguments('echo_pair(routine_pair)'::regprocedure), \
                pg_get_function_result('echo_pair(routine_pair)'::regprocedure), \
                'echo_state(routine_state)'::regprocedure::text, \
                'routine_overload(integer)'::regprocedure::text, \
                'routine_overload(routine_count)'::regprocedure::text",
    );
    assert_eq!(
        data_rows(&catalog),
        [
            "value routine_state|routine_state|value routine_pair|routine_pair|echo_state(routine_state)|routine_overload(integer)|routine_overload(routine_count)"
        ],
        "{}",
        String::from_utf8_lossy(&catalog)
    );
    let altered = run_with(
        &mut engine,
        &mut budget,
        "ALTER FUNCTION routine_overload(routine_count) RENAME TO routine_overload_domain; \
         DROP FUNCTION routine_overload(integer); \
         SELECT routine_overload_domain(1::routine_count)",
    );
    assert_eq!(
        data_rows(&altered),
        ["domain"],
        "{}",
        String::from_utf8_lossy(&altered)
    );
    let moved = run_with(
        &mut engine,
        &mut budget,
        "CREATE SCHEMA routine_type_target; \
         ALTER DOMAIN routine_count RENAME TO routine_count_moved; \
         ALTER DOMAIN routine_count_moved SET SCHEMA routine_type_target",
    );
    let moved_domain = engine
        .storage
        .domain_slot("routine_type_target", "routine_count_moved", 0)
        .expect("moved domain remains visible");
    let echo_count = engine
        .storage
        .routine_slot_by_signature("public", "echo_count", &[ColType::Int4], 0)
        .expect("routine remains visible");
    assert_eq!(
        engine.storage.routine(echo_count).arguments()[0].user_type,
        Some(crate::storage::UserTypeName {
            schema: crate::storage::SqlName::parse("routine_type_target").unwrap(),
            name: crate::storage::SqlName::parse("routine_count_moved").unwrap(),
        })
    );
    assert_eq!(
        engine.storage.routine_type_oid(
            engine.storage.routine(echo_count).arguments()[0].ctype,
            engine.storage.routine(echo_count).arguments()[0].user_type,
            0,
        ),
        Some(crate::sql::types::oid::domain_oid(moved_domain as u16))
    );
    let echo_count_result = match engine.storage.routine(echo_count).kind {
        crate::storage::RoutineKind::Function { result } => result,
        _ => panic!("echo_count is a function"),
    };
    assert_eq!(
        engine
            .storage
            .routine_type_oid(echo_count_result.ctype, echo_count_result.user_type, 0,),
        Some(crate::sql::types::oid::domain_oid(moved_domain as u16))
    );
    let moved_catalog = run_with(
        &mut engine,
        &mut budget,
        "SELECT pg_get_function_arguments(oid), pg_get_function_result(oid) \
           FROM pg_proc WHERE proname = 'echo_count'; \
         SELECT pg_get_function_arguments(oid), pg_get_function_result(oid) \
           FROM pg_proc WHERE proname = 'echo_counts'",
    );
    assert!(
        !String::from_utf8_lossy(&moved).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&moved)
    );
    assert_eq!(
        data_rows(&moved_catalog),
        [
            "value routine_type_target.routine_count_moved|routine_type_target.routine_count_moved",
            "vals routine_type_target.routine_count_moved[]|routine_type_target.routine_count_moved[]",
        ],
        "{}",
        String::from_utf8_lossy(&moved_catalog)
    );
}

#[test]
fn table_routines_accept_and_return_catalog_types() {
    let (mut engine, mut budget) = test_engine();
    let setup = run_with(
        &mut engine,
        &mut budget,
        "CREATE TYPE routine_table_state AS ENUM ('ready', 'done'); \
         CREATE FUNCTION routine_table_rows(value routine_table_state) RETURNS TABLE (state routine_table_state) LANGUAGE SQL AS 'SELECT $1'; \
         CREATE DOMAIN routine_table_count AS integer CHECK (VALUE > 0); \
         CREATE FUNCTION routine_table_overload(value integer) RETURNS TABLE (number integer) LANGUAGE SQL AS 'SELECT 1'; \
         CREATE FUNCTION routine_table_overload(value routine_table_count) RETURNS TABLE (label text) LANGUAGE SQL AS 'SELECT ''domain'''; \
         CREATE FUNCTION routine_table_record_overload(value integer) RETURNS TABLE (number integer, source text) LANGUAGE SQL AS 'SELECT 1, ''integer'''; \
         CREATE FUNCTION routine_table_record_overload(value routine_table_count) RETURNS TABLE (label text, accepted boolean) LANGUAGE SQL AS 'SELECT ''domain'', true'; \
         CREATE TABLE routine_table_inputs(value routine_table_count); \
         INSERT INTO routine_table_inputs VALUES (1)",
    );
    assert!(
        !String::from_utf8_lossy(&setup).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&setup)
    );
    let rows = run_with(
        &mut engine,
        &mut budget,
        "SELECT state::text FROM routine_table_rows('done'::routine_table_state); \
         SELECT label FROM routine_table_overload(1::routine_table_count); \
         SELECT (routine_table_record_overload(input.value)).* \
           FROM routine_table_inputs AS input; \
         SELECT label, label < 'z' \
           FROM routine_table_inputs AS input \
           CROSS JOIN LATERAL routine_table_overload(input.value)",
    );
    assert_eq!(
        data_rows(&rows),
        ["done", "domain", "domain|t", "domain|t"],
        "{}",
        String::from_utf8_lossy(&rows)
    );
    let scalar_star = run_with(
        &mut engine,
        &mut budget,
        "SELECT (routine_table_overload(1::routine_table_count)).*",
    );
    assert!(
        String::from_utf8_lossy(&scalar_star).contains("42809"),
        "{}",
        String::from_utf8_lossy(&scalar_star)
    );
    let correlated_scalar_star = run_with(
        &mut engine,
        &mut budget,
        "SELECT (routine_table_overload(input.value)).* \
           FROM routine_table_inputs AS input",
    );
    assert!(
        String::from_utf8_lossy(&correlated_scalar_star).contains("42809"),
        "{}",
        String::from_utf8_lossy(&correlated_scalar_star)
    );
    let stored = run_with(
        &mut engine,
        &mut budget,
        "CREATE VIEW routine_table_record_view AS \
           SELECT (routine_table_record_overload(input.value)).* \
             FROM routine_table_inputs AS input; \
         DROP FUNCTION routine_table_record_overload(integer); \
         SELECT * FROM routine_table_record_view",
    );
    assert_eq!(
        data_rows(&stored),
        ["domain|t"],
        "{}",
        String::from_utf8_lossy(&stored)
    );
}

