#[test]
fn publication_column_lists_are_typed_catalog_state_and_survive_replay() {
    let mut config = test_config("publication-column-lists-replay");
    config.object_store_on = true;
    config.object_store_sim = true;
    config.object_store_namespace = format!("publication-column-lists-{}", std::process::id());
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
    let mut budget = Budget::new(1 << 30);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    run_with(
        &mut engine,
        &mut budget,
        "CREATE TABLE publication_projected (id int PRIMARY KEY, visible text, hidden text); \
         CREATE PUBLICATION projected_changes FOR TABLE publication_projected (id, visible) WHERE (id > 0) \
         WITH (publish = 'insert, update, delete')",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT prattrs::text FROM pg_publication_rel"
        )),
        ["1 2"],
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT pg_get_expr(prqual, prrelid) FROM pg_publication_rel"
        )),
        ["id > 0"],
    );
    assert!(engine.checkpoint().unwrap());
    drop(engine);
    let mut replay_budget = Budget::new(1 << 30);
    let mut replayed = Engine::new(&config, &mut replay_budget).unwrap();
    assert_eq!(
        data_rows(&run_with(
            &mut replayed,
            &mut replay_budget,
            "SELECT prattrs::text FROM pg_publication_rel"
        )),
        ["1 2"],
        "publication projections are WAL-replayable catalog state"
    );
    assert_eq!(
        data_rows(&run_with(
            &mut replayed,
            &mut replay_budget,
            "SELECT pg_get_expr(prqual, prrelid) FROM pg_publication_rel"
        )),
        ["id > 0"],
        "publication filters survive checkpoint recovery"
    );
    crate::object_store::sim::drop_namespace(&config.object_store_namespace);
}

#[test]
fn disabled_subscriptions_are_durable_catalog_objects() {
    let config = test_config("subscription-catalog-replay");
    let mut budget = Budget::new(1 << 27);
    let mut engine = Engine::new(&config, &mut budget).unwrap();
    let rejected = run_with(
        &mut engine,
        &mut budget,
        "CREATE SUBSCRIPTION live_changes CONNECTION \
         'host=publisher port=5432' \
         PUBLICATION changes",
    );
    assert!(
        String::from_utf8_lossy(&rejected).contains("requires a numeric host"),
        "{}",
        String::from_utf8_lossy(&rejected)
    );
    let named_slot = run_with(
        &mut engine,
        &mut budget,
        "CREATE SUBSCRIPTION named_slot_changes CONNECTION \
         'host=127.0.0.1 port=5432 user=repl dbname=publisher sslmode=disable' \
         PUBLICATION changes WITH (connect = false)",
    );
    assert!(
        !String::from_utf8_lossy(&named_slot).contains("ERROR"),
        "{}",
        String::from_utf8_lossy(&named_slot)
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT subenabled, subslotname FROM pg_subscription WHERE subname = 'named_slot_changes'",
        )),
        ["f|named_slot_changes"]
    );
    run_with(
        &mut engine,
        &mut budget,
        "DROP SUBSCRIPTION named_slot_changes",
    );
    let contradictory = run_with(
        &mut engine,
        &mut budget,
        "CREATE SUBSCRIPTION contradictory_changes CONNECTION 'host=publisher' \
         PUBLICATION changes WITH (connect = false, enabled = true)",
    );
    assert!(
        String::from_utf8_lossy(&contradictory).contains("connect = false requires"),
        "{}",
        String::from_utf8_lossy(&contradictory)
    );
    run_with(
        &mut engine,
        &mut budget,
        "BEGIN; \
         CREATE SUBSCRIPTION archived_changes CONNECTION \
         'host=publisher port=5432' \
         PUBLICATION sales, inventory \
         WITH (connect = false, slot_name = NONE); \
         COMMIT",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT subname, subenabled, subconninfo, subslotname, subpublications \
             FROM pg_subscription",
        )),
        ["archived_changes|f|host=publisher port=5432|NULL|{sales,inventory}"]
    );
    assert!(
        engine.subscription_endpoint("archived_changes").is_none(),
        "a disabled subscription keeps its PostgreSQL conninfo without claiming a local client endpoint"
    );
    run_with(
        &mut engine,
        &mut budget,
        "BEGIN; DROP SUBSCRIPTION archived_changes; ROLLBACK",
    );
    assert_eq!(
        data_rows(&run_with(
            &mut engine,
            &mut budget,
            "SELECT count(*) FROM pg_subscription",
        )),
        ["1"]
    );
    drop(engine);
    let mut replay_budget = Budget::new(1 << 29);
    let mut replayed = Engine::new(&config, &mut replay_budget).unwrap();
    assert_eq!(
        data_rows(&run_with(
            &mut replayed,
            &mut replay_budget,
            "SELECT subname, subenabled, subconninfo, subslotname, subpublications \
             FROM pg_subscription",
        )),
        ["archived_changes|f|host=publisher port=5432|NULL|{sales,inventory}"],
        "the fixed subscription state and its publication identities survive WAL replay"
    );
    run_with(
        &mut replayed,
        &mut replay_budget,
        "DROP SUBSCRIPTION archived_changes",
    );
    drop(replayed);
    let mut dropped_budget = Budget::new(1 << 27);
    let mut dropped = Engine::new(&config, &mut dropped_budget).unwrap();
    assert_eq!(
        data_rows(&run_with(
            &mut dropped,
            &mut dropped_budget,
            "SELECT count(*) FROM pg_subscription",
        )),
        ["0"],
        "DROP SUBSCRIPTION survives WAL replay rather than reviving catalog state"
    );
}

